struct AuditLogTimeRangeInput {
    /// Inclusive canonical UTC start time.
    #[schemars(regex(
        pattern = r"^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(?:[.][0-9]{3})?Z$"
    ))]
    start: String,
    /// Inclusive canonical UTC end time, no more than 90 days after the start.
    #[schemars(regex(
        pattern = r"^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(?:[.][0-9]{3})?Z$"
    ))]
    end: String,
}

#[derive(Debug, Deserialize, JsonSchema)]
#[serde(transparent)]
struct AuditLogEventTypeInput(
    #[schemars(
        regex(pattern = r"^[a-z0-9]+(?:-[a-z0-9]+)*$"),
        length(min = 1, max = 128)
    )]
    String,
);

#[derive(Debug, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct AuditLogsListInput {
    /// Optional exact project identifier; omission searches organization-wide events.
    #[schemars(regex(pattern = r"^[A-Za-z0-9_-]{1,128}$"))]
    project_id: Option<String>,
    /// Optional exact environment slug embedded in event metadata.
    #[schemars(
        regex(pattern = r"^[a-z0-9]+(?:-[a-z0-9]+)*$"),
        length(min = 1, max = 64)
    )]
    environment: Option<String>,
    /// Optional principal-family filter.
    actor_type: Option<AuditLogActorType>,
    /// Optional client-family filter.
    user_agent_type: Option<AuditLogUserAgentType>,
    /// Optional normalized absolute secret path embedded in event metadata.
    #[schemars(length(min = 1, max = 2048))]
    secret_path: Option<String>,
    /// Optional bounded secret key embedded in event metadata.
    #[schemars(length(min = 1, max = 512))]
    secret_key: Option<String>,
    /// Optional non-empty set of canonical audit event types.
    #[schemars(length(min = 1, max = 32))]
    event_types: Option<Vec<AuditLogEventTypeInput>>,
    /// Optional complete UTC interval; partial ranges are not accepted.
    time_range: Option<AuditLogTimeRangeInput>,
    /// Zero-based upstream collection offset.
    #[serde(default)]
    #[schemars(range(min = 0, max = 100_000))]
    offset: u32,
    /// Maximum records returned in this response.
    #[serde(default = "default_page_limit")]
    #[schemars(range(min = 1, max = 100))]
    limit: u16,
}

impl AuditLogsListInput {
    fn into_request(self) -> Result<AuditLogListRequest, McpError> {
        let mut request = AuditLogListRequest::new(page_request(self.offset, self.limit)?);
        if let Some(project_id) = self.project_id {
            request = request.with_project(ProjectId::new(project_id).map_err(invalid_input)?);
        }
        if let Some(environment) = self.environment {
            request =
                request.with_environment(EnvironmentSlug::new(environment).map_err(invalid_input)?);
        }
        if let Some(actor_type) = self.actor_type {
            request = request.with_actor_type(actor_type);
        }
        if let Some(user_agent_type) = self.user_agent_type {
            request = request.with_user_agent_type(user_agent_type);
        }
        if let Some(secret_path) = self.secret_path {
            request =
                request.with_secret_path(SecretPath::new(secret_path).map_err(invalid_input)?);
        }
        if let Some(secret_key) = self.secret_key {
            request = request.with_secret_key(SecretName::new(secret_key).map_err(invalid_input)?);
        }
        if let Some(event_types) = self.event_types {
            let event_types = event_types
                .into_iter()
                .map(|event_type| AuditLogEventType::new(event_type.0))
                .collect::<Result<Vec<_>, _>>()
                .map_err(invalid_input)?;
            request = request
                .with_event_types(event_types)
                .map_err(invalid_input)?;
        }
        if let Some(time_range) = self.time_range {
            request = request
                .with_time_range(
                    AuditLogTimestamp::new(time_range.start).map_err(invalid_input)?,
                    AuditLogTimestamp::new(time_range.end).map_err(invalid_input)?,
                )
                .map_err(invalid_input)?;
        }
        Ok(request)
    }
}

#[derive(Debug, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct AppConnectionsListInput {
    /// Optional exact project identifier; omission lists organization-level and visible project connections.
    #[schemars(regex(pattern = r"^[A-Za-z0-9_-]{1,128}$"))]
    project_id: Option<String>,
    /// Zero-based local collection offset.
    #[serde(default)]
    #[schemars(range(min = 0, max = 100_000))]
    offset: u32,
    /// Maximum records returned in this response.
    #[serde(default = "default_page_limit")]
    #[schemars(range(min = 1, max = 100))]
    limit: u16,
}

impl AppConnectionsListInput {
    fn into_parts(self) -> Result<(Option<ProjectId>, PageRequest), McpError> {
        let project_id = self
            .project_id
            .map(ProjectId::new)
            .transpose()
            .map_err(invalid_input)?;
        let page = page_request(self.offset, self.limit)?;
        Ok((project_id, page))
    }
}

