#[derive(Debug, Deserialize, JsonSchema)]
#[serde(tag = "kind", rename_all = "camelCase", deny_unknown_fields)]
enum ProjectChangeInput {
    /// Replace the project display name.
    Name {
        /// New project display name.
        #[schemars(length(min = 1, max = 64))]
        name: String,
    },
    /// Replace or clear the project description.
    Description {
        /// New description; use an empty string to clear it.
        #[schemars(length(max = 1_024))]
        description: String,
    },
    /// Replace the project slug.
    Slug {
        /// New stable project slug.
        #[schemars(
            regex(pattern = r"^[a-z0-9]+(?:[_-][a-z0-9]+)*$"),
            length(min = 1, max = 64)
        )]
        slug: String,
    },
    /// Enable or disable deletion protection.
    DeleteProtection {
        /// New deletion-protection state.
        enabled: bool,
    },
    /// Enable or disable automatic secret-name capitalization.
    AutoCapitalization {
        /// New automatic-capitalization state.
        enabled: bool,
    },
    /// Require or stop requiring encrypted secret metadata.
    EncryptedSecretMetadata {
        /// New encrypted-metadata enforcement state.
        enabled: bool,
    },
    /// Enable or disable secret sharing.
    SecretSharing {
        /// New secret-sharing state.
        enabled: bool,
    },
    /// Change the point-in-time version retention limit.
    PointInTimeVersionLimit {
        /// Number of point-in-time versions retained per secret.
        #[schemars(range(min = 1, max = 100))]
        limit: u8,
    },
}

impl ProjectChangeInput {
    fn into_change(self) -> Result<ProjectChange, McpError> {
        match self {
            Self::Name { name } => Ok(ProjectChange::Name(
                ProjectName::new(name).map_err(invalid_input)?,
            )),
            Self::Description { description } => Ok(ProjectChange::Description(
                ProjectDescription::new(description).map_err(invalid_input)?,
            )),
            Self::Slug { slug } => Ok(ProjectChange::Slug(
                ProjectSlug::new(slug).map_err(invalid_input)?,
            )),
            Self::DeleteProtection { enabled } => Ok(ProjectChange::DeleteProtection(enabled)),
            Self::AutoCapitalization { enabled } => Ok(ProjectChange::AutoCapitalization(enabled)),
            Self::EncryptedSecretMetadata { enabled } => {
                Ok(ProjectChange::EncryptedSecretMetadata(enabled))
            }
            Self::SecretSharing { enabled } => Ok(ProjectChange::SecretSharing(enabled)),
            Self::PointInTimeVersionLimit { limit } => Ok(ProjectChange::PointInTimeVersionLimit(
                PointInTimeVersionLimit::new(limit).map_err(invalid_input)?,
            )),
        }
    }
}

