#[derive(Debug, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct FolderBatchUpdateInput {
    /// Opaque project identifier shared by every entry.
    #[schemars(regex(pattern = r"^[A-Za-z0-9_-]{1,128}$"))]
    project_id: String,
    /// Between one and fifty complete folder updates with unique IDs.
    #[schemars(length(min = 1, max = 50))]
    folders: Vec<FolderBatchUpdateEntryInput>,
}

impl FolderBatchUpdateInput {
    fn into_parts(self) -> Result<(ProjectId, Vec<FolderBatchUpdate>), McpError> {
        let project_id = ProjectId::new(self.project_id).map_err(invalid_input)?;
        if self.folders.is_empty() || self.folders.len() > MAX_FOLDER_BATCH_SIZE {
            return Err(McpError::invalid_params(
                "folders must contain between 1 and 50 entries",
                None,
            ));
        }
        let updates = self
            .folders
            .into_iter()
            .map(FolderBatchUpdateEntryInput::into_update)
            .collect::<Result<Vec<_>, _>>()?;
        Ok((project_id, updates))
    }
}

