#[derive(Debug, Deserialize, JsonSchema)]
#[serde(tag = "kind", rename_all = "camelCase", deny_unknown_fields)]
enum UniversalAuthChangeInput {
    /// Replace all mutually constrained token lifetime fields together.
    TokenLifetime {
        /// Ordinary access-token lifetime in seconds.
        #[serde(rename = "accessTokenTTL")]
        #[schemars(range(min = 0, max = 315_360_000))]
        access_token_ttl: u32,
        /// Maximum renewable access-token lifetime in seconds.
        #[serde(rename = "accessTokenMaxTTL")]
        #[schemars(range(min = 0, max = 315_360_000))]
        access_token_max_ttl: u32,
        /// Periodic-token interval; zero disables periodic tokens.
        #[serde(rename = "accessTokenPeriod")]
        #[schemars(range(min = 0, max = 315_360_000))]
        access_token_period: u32,
    },
    /// Replace the token use limit; zero means unlimited.
    AccessTokenUseLimit {
        /// Complete desired use limit.
        limit: u32,
    },
    /// Replace the complete lockout policy.
    LockoutPolicy {
        /// Whether repeated authentication failures cause lockout.
        enabled: bool,
        /// Failed attempts that trigger lockout.
        #[schemars(range(min = 1, max = 30))]
        threshold: u8,
        /// Lockout duration in seconds.
        #[serde(rename = "durationSeconds")]
        #[schemars(range(min = 30, max = 86_400))]
        duration_seconds: u32,
        /// Failure-counter reset interval in seconds.
        #[serde(rename = "counterResetSeconds")]
        #[schemars(range(min = 5, max = 3_600))]
        counter_reset_seconds: u32,
    },
}

impl UniversalAuthChangeInput {
    fn into_change(self) -> Result<UniversalAuthChange, McpError> {
        match self {
            Self::TokenLifetime {
                access_token_ttl,
                access_token_max_ttl,
                access_token_period,
            } => UniversalAuthChange::token_lifetime(
                access_token_ttl,
                access_token_max_ttl,
                access_token_period,
            )
            .map_err(invalid_input),
            Self::AccessTokenUseLimit { limit } => {
                Ok(UniversalAuthChange::AccessTokenUseLimit(limit))
            }
            Self::LockoutPolicy {
                enabled,
                threshold,
                duration_seconds,
                counter_reset_seconds,
            } => Ok(UniversalAuthChange::Lockout(
                UniversalAuthLockoutPolicy::new(
                    enabled,
                    threshold,
                    duration_seconds,
                    counter_reset_seconds,
                )
                .map_err(invalid_input)?,
            )),
        }
    }
}

