#[derive(Debug, Deserialize, JsonSchema)]
#[serde(tag = "kind", rename_all = "camelCase", deny_unknown_fields)]
enum KubernetesTokenReviewerJwtChangeInput {
    /// Keep the stored credential without reading it first.
    Preserve,
    /// Replace the stored credential.
    Replace {
        /// New token-reviewer JWT sent only to Infisical.
        #[serde(deserialize_with = "deserialize_secret_input")]
        #[schemars(with = "String", length(max = 16_384))]
        value: SecretValue,
    },
    /// Clear the stored credential.
    Clear,
}

impl From<KubernetesTokenReviewerJwtChangeInput> for KubernetesTokenReviewerJwtChange {
    fn from(value: KubernetesTokenReviewerJwtChangeInput) -> Self {
        match value {
            KubernetesTokenReviewerJwtChangeInput::Preserve => Self::Preserve,
            KubernetesTokenReviewerJwtChangeInput::Replace { value } => Self::Replace(value),
            KubernetesTokenReviewerJwtChangeInput::Clear => Self::Clear,
        }
    }
}

#[derive(Debug, Deserialize, JsonSchema)]
#[serde(tag = "kind", rename_all = "camelCase", deny_unknown_fields)]
enum KubernetesAuthChangeInput {
    /// Replace both mutually constrained access-token lifetime fields together.
    TokenLifetime {
        /// Ordinary access-token lifetime in seconds.
        #[serde(rename = "accessTokenTTL")]
        #[schemars(range(min = 0, max = 315_360_000))]
        access_token_ttl: u32,
        /// Maximum renewable access-token lifetime in seconds.
        #[serde(rename = "accessTokenMaxTTL")]
        #[schemars(range(min = 0, max = 315_360_000))]
        access_token_max_ttl: u32,
    },
    /// Replace the token use limit; zero means unlimited.
    AccessTokenUseLimit {
        /// Complete desired use limit.
        limit: u32,
    },
    /// Replace the complete namespace, service-account, and audience policy.
    WorkloadPolicy {
        /// Explicit namespace names or glob patterns.
        #[serde(rename = "allowedNamespaces")]
        #[schemars(length(min = 1, max = 100))]
        allowed_namespaces: Vec<String>,
        /// Explicit service-account names or glob patterns.
        #[serde(rename = "allowedNames")]
        #[schemars(length(min = 1, max = 100))]
        allowed_names: Vec<String>,
        /// Exact Kubernetes token audience.
        #[serde(rename = "allowedAudience")]
        #[schemars(length(min = 1, max = 2_048))]
        allowed_audience: String,
    },
    /// Replace the direct Kubernetes API reviewer configuration and leave paid gateway routing.
    DirectReviewer {
        /// HTTPS Kubernetes API endpoint used for `TokenReview` calls.
        #[serde(rename = "kubernetesHost")]
        #[schemars(regex(pattern = r"^https://[A-Za-z0-9:./-]+$"), length(max = 2_048))]
        kubernetes_host: String,
        /// PEM CA bundle required exactly when TLS verification is enabled.
        #[serde(rename = "caCert")]
        #[schemars(length(max = 131_072))]
        ca_cert: Option<String>,
        /// Verify the Kubernetes API certificate using the supplied CA bundle.
        #[serde(rename = "verifyTlsCertificate")]
        verify_tls_certificate: bool,
        /// Explicit treatment of the stored token-reviewer credential.
        #[serde(rename = "tokenReviewerJwt")]
        token_reviewer_jwt: KubernetesTokenReviewerJwtChangeInput,
    },
}

impl KubernetesAuthChangeInput {
    fn into_change(self) -> Result<KubernetesAuthChange, McpError> {
        match self {
            Self::TokenLifetime {
                access_token_ttl,
                access_token_max_ttl,
            } => KubernetesAuthChange::token_lifetime(access_token_ttl, access_token_max_ttl)
                .map_err(invalid_input),
            Self::AccessTokenUseLimit { limit } => {
                Ok(KubernetesAuthChange::AccessTokenUseLimit(limit))
            }
            Self::WorkloadPolicy {
                allowed_namespaces,
                allowed_names,
                allowed_audience,
            } => KubernetesAuthChange::workload_policy(
                &allowed_namespaces,
                &allowed_names,
                allowed_audience,
            )
            .map_err(invalid_input),
            Self::DirectReviewer {
                kubernetes_host,
                ca_cert,
                verify_tls_certificate,
                token_reviewer_jwt,
            } => KubernetesAuthChange::direct_reviewer(
                kubernetes_host,
                ca_cert,
                verify_tls_certificate,
                token_reviewer_jwt.into(),
            )
            .map_err(invalid_input),
        }
    }
}

