#[derive(Debug, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
struct SecretBatchValueMutationInput {
    /// Exact project, environment, and path shared by every batch entry.
    scope: ExactSecretScopeInput,
    /// Between one and fifty uniquely named shared secrets.
    #[schemars(length(min = 1, max = 50))]
    secrets: Vec<SecretBatchValueInput>,
}

impl SecretBatchValueMutationInput {
    fn into_parts(self) -> Result<(SecretScope, Vec<SecretValueMutation>), McpError> {
        let scope = self.scope.into_scope()?;
        let secrets = self
            .secrets
            .into_iter()
            .map(|secret| {
                SecretName::new(secret.name)
                    .map(|name| SecretValueMutation::new(name, secret.secret_value))
                    .map_err(invalid_input)
            })
            .collect::<Result<Vec<_>, _>>()?;
        Ok((scope, secrets))
    }
}

