fn default_sql_ssl_reject_unauthorized() -> bool {
    true
}

#[derive(Debug, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct SqlDynamicSecretProviderInputsInput {
    /// Exact pinned SQL driver.
    client: SqlDynamicSecretClientInput,
    /// Plain database host name or IP address without a URL scheme.
    #[schemars(length(min = 1, max = 253))]
    host: String,
    /// Provider TCP port.
    #[schemars(range(min = 1, max = 65_535))]
    port: u16,
    /// Database used by the root connection and statement templates.
    #[schemars(length(min = 1, max = 256))]
    database: String,
    /// Root provider username used only by Infisical.
    #[schemars(length(min = 1, max = 256))]
    username: String,
    /// Root provider password sent only to Infisical and never returned.
    #[serde(deserialize_with = "deserialize_secret_input")]
    #[schemars(with = "String", length(min = 1, max = 16_384))]
    password: SecretValue,
    /// Complete generated-password policy; omission selects the pinned provider default.
    password_requirements: Option<SqlDynamicSecretPasswordRequirementsInput>,
    /// SQL template using only username, password, expiration, and database placeholders.
    #[schemars(length(min = 1, max = 16_384))]
    creation_statement: String,
    /// SQL template using only username and database placeholders.
    #[schemars(length(min = 1, max = 16_384))]
    revocation_statement: String,
    /// Optional SQL template using only username, expiration, and database placeholders.
    #[schemars(length(min = 1, max = 16_384))]
    renew_statement: Option<String>,
    /// Optional bounded CA bundle used to authenticate the SQL server.
    #[schemars(length(min = 1, max = 65_536))]
    ca: Option<String>,
    /// MSSQL encryption switch retained explicitly in the provider configuration.
    #[serde(default)]
    ssl_enabled: bool,
    /// Reject provider certificates that do not validate against trusted roots.
    #[serde(default = "default_sql_ssl_reject_unauthorized")]
    ssl_reject_unauthorized: bool,
    /// Direct, gateway, or gateway-pool routing.
    route: SqlDynamicSecretRouteInput,
}

impl SqlDynamicSecretProviderInputsInput {
    fn into_inputs(self) -> Result<SqlDynamicSecretInputs, McpError> {
        let client = SqlDynamicSecretClient::from(self.client);
        let connection = SqlDynamicSecretConnection::new(
            client,
            self.host,
            self.port,
            self.database,
            self.username,
        )
        .map_err(invalid_input)?;
        let statements = SqlDynamicSecretStatements::new(
            self.creation_statement,
            self.revocation_statement,
            self.renew_statement,
        )
        .map_err(invalid_input)?;
        let password_requirements = self
            .password_requirements
            .map(|requirements| requirements.into_requirements(client))
            .transpose()?
            .unwrap_or_else(|| SqlDynamicSecretPasswordRequirements::provider_default(client));
        let tls = SqlDynamicSecretTls::new(self.ca, self.ssl_enabled, self.ssl_reject_unauthorized)
            .map_err(invalid_input)?;
        let route = self.route.into_route()?;
        SqlDynamicSecretInputs::new(
            connection,
            self.password,
            statements,
            password_requirements,
            tls,
            route,
        )
        .map_err(invalid_input)
    }
}

/// Provider-tagged configuration accepted by generic dynamic-secret mutations.
