enum DynamicSecretProviderInput {
    /// Infisical's generic SQL database provider.
    SqlDatabase {
        /// Complete SQL provider inputs.
        inputs: SqlDynamicSecretProviderInputsInput,
    },
}

impl DynamicSecretProviderInput {
    fn into_sql_inputs(self) -> Result<SqlDynamicSecretInputs, McpError> {
        match self {
            Self::SqlDatabase { inputs } => inputs.into_inputs(),
        }
    }
}

#[derive(Debug, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct DynamicSecretCreateInput {
    /// Exact project, environment, and path receiving the configuration.
    scope: DynamicSecretScopeInput,
    /// Canonical dynamic-secret name.
    #[schemars(regex(pattern = r"^[a-z0-9]+(?:-[a-z0-9]+)*$"), length(max = 64))]
    name: String,
    /// Default lease lifetime in whole seconds.
    #[schemars(range(min = 60, max = 315_360_000))]
    default_ttl_seconds: u32,
    /// Optional maximum caller-selectable lifetime in whole seconds.
    #[schemars(range(min = 60, max = 315_360_000))]
    max_ttl_seconds: Option<u32>,
    /// One exact provider-tagged configuration.
    provider: DynamicSecretProviderInput,
}

impl DynamicSecretCreateInput {
    fn into_parts(self) -> Result<(DynamicSecretScope, SqlDynamicSecretCreation), McpError> {
        let scope = self.scope.into_scope()?;
        let name = DynamicSecretName::new(self.name).map_err(invalid_input)?;
        let default_ttl =
            DynamicSecretTtlSeconds::new(self.default_ttl_seconds).map_err(invalid_input)?;
        let max_ttl = self
            .max_ttl_seconds
            .map(DynamicSecretTtlSeconds::new)
            .transpose()
            .map_err(invalid_input)?;
        let inputs = self.provider.into_sql_inputs()?;
        let creation = SqlDynamicSecretCreation::new(name, default_ttl, max_ttl, inputs)
            .map_err(invalid_input)?;
        Ok((scope, creation))
    }
}

