#[derive(Debug, JsonSchema)]
#[schemars(rename_all = "camelCase")]
struct IssuedSshCertificateOutput {
    /// Canonical unsigned 64-bit decimal serial, kept as text to preserve JSON precision.
    #[schemars(regex(pattern = r"^(?:0|[1-9][0-9]{0,19})$"))]
    serial_number: String,
    /// Canonical OpenSSH certificate line whose trust and requested semantics were verified.
    signed_key: String,
    /// Explicitly revealed unencrypted OpenSSH private key, present only for inline
    /// delivery. This field is sensitive.
    #[schemars(with = "Option<String>")]
    private_key: Option<SecretValue>,
    /// Out-of-context reference to the one-time private key, present only for reference
    /// delivery. The envelope's data carries a privateKey field.
    secret_file: Option<SecretFileReference>,
    /// Canonical public half of the verified generated key pair.
    public_key: String,
    /// Exact reflected key-pair algorithm.
    key_algorithm: SshKeyAlgorithm,
}

impl IssuedSshCertificateOutput {
    fn deliver(
        value: IssuedSshCertificate,
        disposition: SecretDisposition<'_>,
    ) -> Result<Self, McpError> {
        let secret_file = disposition.stage(
            SSH_CERTIFICATES_ISSUE_TOOL,
            || serde_json::json!({ "privateKey": value.private_key.expose_secret() }),
        )?;
        Ok(Self {
            serial_number: value.serial_number,
            signed_key: value.signed_key,
            private_key: secret_file.is_none().then_some(value.private_key),
            secret_file,
            public_key: value.public_key,
            key_algorithm: value.key_algorithm,
        })
    }
}

impl Serialize for IssuedSshCertificateOutput {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: Serializer,
    {
        let mut output = serializer.serialize_struct("IssuedSshCertificateOutput", 5)?;
        output.serialize_field("serialNumber", &self.serial_number)?;
        output.serialize_field("signedKey", &self.signed_key)?;
        if let Some(value) = &self.private_key {
            output.serialize_field("privateKey", value.expose_secret())?;
        }
        if let Some(file) = &self.secret_file {
            output.serialize_field("secretFile", file)?;
        }
        output.serialize_field("publicKey", &self.public_key)?;
        output.serialize_field("keyAlgorithm", &self.key_algorithm)?;
        output.end()
    }
}

