macro_rules! code_signer_member_mutation_input {
    ($name:ident { $($operation_field:tt)* }) => {
        #[derive(Debug, Deserialize, JsonSchema)]
        #[serde(rename_all = "camelCase", deny_unknown_fields)]
        struct $name {
            /// Exact project and signer identifiers whose membership changes.
            target: CodeSignerTargetInput,
            /// User, machine-identity, or group membership family.
            member_kind: CodeSignerMemberKind,
            /// Canonical UUID of the exact user, machine identity, or group.
            #[schemars(regex(
                pattern = r"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$"
            ))]
            member_id: String,
            $($operation_field)*
            /// Must be true to acknowledge a persistent governance mutation.
            confirm: bool,
        }
    };
}

