#[derive(Debug, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct CertificateImportInput {
    /// Canonical UUID of the Certificate Manager project receiving the certificate.
    #[schemars(regex(
        pattern = r"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$"
    ))]
    project_id: String,
    /// Out-of-context upload containing exactly one PEM certificate.
    certificate_file: SecretFileInput,
    /// Optional out-of-context upload containing the matching PEM private key.
    private_key_file: Option<SecretFileInput>,
    /// Optional out-of-context upload containing the ordered PEM issuer chain.
    certificate_chain_file: Option<SecretFileInput>,
    /// Optional inventory display name accepted by Infisical.
    #[schemars(length(min = 1, max = 255))]
    friendly_name: Option<String>,
    /// Optional canonical PKI collection UUID.
    #[schemars(regex(
        pattern = r"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$"
    ))]
    pki_collection_id: Option<String>,
    /// Optional canonical application UUID.
    #[schemars(regex(
        pattern = r"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$"
    ))]
    application_id: Option<String>,
    /// Must be true before uploaded material is consumed and imported.
    confirm: bool,
}

impl CertificateImportInput {
    fn into_parts(
        self,
        files: Option<&SecretFilePlane>,
    ) -> Result<(CertificateAuthorityProjectId, CertificateImport), McpError> {
        let project_id =
            CertificateAuthorityProjectId::new(self.project_id).map_err(invalid_input)?;
        let certificate =
            resolve_uploaded_secret(files, &self.certificate_file, "certificateFile")?;
        let private_key = self
            .private_key_file
            .as_ref()
            .map(|reference| resolve_uploaded_secret(files, reference, "privateKeyFile"))
            .transpose()?;
        let certificate_chain = self
            .certificate_chain_file
            .as_ref()
            .map(|reference| resolve_uploaded_secret(files, reference, "certificateChainFile"))
            .transpose()?;
        let certificate_import = CertificateImport::new(
            certificate,
            private_key,
            certificate_chain,
            self.friendly_name,
            self.pki_collection_id,
            self.application_id,
        )
        .map_err(invalid_input)?;
        Ok((project_id, certificate_import))
    }
}

