#[derive(Debug, JsonSchema)]
#[schemars(rename_all = "camelCase")]
struct CertificateBundleOutput {
    project_id: String,
    certificate_id: String,
    serial_number: String,
    certificate: String,
    certificate_chain: String,
    /// Stored private key, present only for explicit inline delivery.
    #[schemars(with = "Option<String>")]
    private_key: Option<SecretValue>,
    /// Out-of-context private-key reference.
    secret_file: Option<SecretFileReference>,
}

impl CertificateBundleOutput {
    fn deliver(
        value: CertificateBundle,
        disposition: SecretDisposition<'_>,
    ) -> Result<Self, McpError> {
        let secret_file = match value.private_key.as_ref() {
            Some(private_key) => disposition.stage(
                CERTIFICATES_BUNDLE_REVEAL_TOOL,
                || serde_json::json!({ "privateKey": private_key.expose_secret() }),
            )?,
            None => None,
        };
        Ok(Self {
            project_id: value.project_id,
            certificate_id: value.certificate_id,
            serial_number: value.serial_number,
            certificate: value.certificate,
            certificate_chain: value.certificate_chain,
            private_key: secret_file.is_none().then_some(value.private_key).flatten(),
            secret_file,
        })
    }
}

impl Serialize for CertificateBundleOutput {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: Serializer,
    {
        let mut output = serializer.serialize_struct("CertificateBundleOutput", 7)?;
        output.serialize_field("projectId", &self.project_id)?;
        output.serialize_field("certificateId", &self.certificate_id)?;
        output.serialize_field("serialNumber", &self.serial_number)?;
        output.serialize_field("certificate", &self.certificate)?;
        output.serialize_field("certificateChain", &self.certificate_chain)?;
        if let Some(value) = &self.private_key {
            output.serialize_field("privateKey", value.expose_secret())?;
        }
        if let Some(value) = &self.secret_file {
            output.serialize_field("secretFile", value)?;
        }
        output.end()
    }
}

