#[derive(Debug, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct CertificateIssueMetadataInput {
    #[schemars(length(min = 1, max = 255))]
    key: String,
    #[schemars(length(max = 1020))]
    value: String,
}

impl CertificateIssueInput {
    fn into_parts(
        self,
    ) -> Result<
        (
            CertificateAuthorityProjectId,
            CertificateIssuance,
            bool,
            Option<SecretDeliveryMode>,
            bool,
        ),
        McpError,
    > {
        let project_id =
            CertificateAuthorityProjectId::new(self.project_id).map_err(invalid_input)?;
        let profile_id = CertificateProfileId::new(self.profile_id).map_err(invalid_input)?;
        let (method, may_return_private_key) = match self.request {
            CertificateIssueMethodInput::Managed { attributes } => (
                CertificateIssuanceMethod::Managed(attributes.into_attributes()?),
                true,
            ),
            CertificateIssueMethodInput::Csr {
                csr,
                validity,
                basic_constraints,
            } => (
                CertificateIssuanceMethod::csr(
                    csr,
                    validity.map(TryInto::try_into).transpose()?,
                    basic_constraints.map(TryInto::try_into).transpose()?,
                )
                .map_err(invalid_input)?,
                false,
            ),
        };
        let metadata = self
            .metadata
            .map(|values| {
                values
                    .into_iter()
                    .map(|value| {
                        CertificateIssuanceMetadata::new(value.key, value.value)
                            .map_err(invalid_input)
                    })
                    .collect::<Result<Vec<_>, _>>()
            })
            .transpose()?;
        let issuance = CertificateIssuance::new(
            profile_id,
            self.application_id,
            method,
            self.remove_roots_from_chain,
            metadata,
        )
        .map_err(invalid_input)?;
        Ok((
            project_id,
            issuance,
            self.confirm,
            self.delivery,
            may_return_private_key,
        ))
    }
}

impl CertificateIssueAttributesInput {
    fn into_attributes(self) -> Result<CertificateIssuanceAttributes, McpError> {
        CertificateIssuanceAttributes::new(
            self.common_name,
            self.organization,
            self.organizational_unit,
            self.country,
            self.state,
            self.locality,
            self.key_usages,
            self.extended_key_usages,
            self.alternative_names
                .map(|values| {
                    values
                        .into_iter()
                        .map(|value| {
                            CertificateIssuanceSan::new(value.san_type, value.value)
                                .map_err(invalid_input)
                        })
                        .collect::<Result<Vec<_>, _>>()
                })
                .transpose()?,
            self.validity.map(TryInto::try_into).transpose()?,
            self.signature_algorithm,
            self.key_algorithm,
            self.basic_constraints.map(TryInto::try_into).transpose()?,
        )
        .map_err(invalid_input)
    }
}

impl TryFrom<CertificateIssueValidityInput> for CertificateIssuanceValidity {
    type Error = McpError;

    fn try_from(value: CertificateIssueValidityInput) -> Result<Self, Self::Error> {
        match value {
            CertificateIssueValidityInput::Ttl { ttl } => Ok(Self::Ttl {
                ttl: CertificatePolicyMaxValidity::new(ttl).map_err(invalid_input)?,
            }),
            CertificateIssueValidityInput::Window {
                not_before,
                not_after,
            } => Self::window(not_before, not_after).map_err(invalid_input),
        }
    }
}

impl TryFrom<CertificateIssueBasicConstraintsInput> for CertificateIssuanceBasicConstraints {
    type Error = McpError;

    fn try_from(value: CertificateIssueBasicConstraintsInput) -> Result<Self, Self::Error> {
        Self::new(value.is_ca, value.path_length).map_err(invalid_input)
    }
}

#[derive(Debug, Clone, Copy, Serialize, JsonSchema)]
#[serde(rename_all = "camelCase")]
enum CertificateIssueOutcomeKind {
    Issued,
    Pending,
}

#[derive(Debug, JsonSchema)]
#[schemars(rename_all = "camelCase")]
struct CertificateIssueOutput {
    outcome: CertificateIssueOutcomeKind,
    project_id: String,
    profile_id: String,
    request_id: String,
    status: Option<CertificateRequestStatus>,
    certificate_id: Option<String>,
    serial_number: Option<String>,
    certificate: Option<String>,
    issuing_ca_certificate: Option<String>,
    certificate_chain: Option<String>,
    /// Immediate managed private key, present only for inline delivery.
    #[schemars(with = "Option<String>")]
    private_key: Option<SecretValue>,
    /// Out-of-context private-key reference for immediate managed issuance.
    secret_file: Option<SecretFileReference>,
}

impl CertificateIssueOutput {
    fn deliver(
        value: CertificateIssuanceOutcome,
        disposition: SecretDisposition<'_>,
    ) -> Result<Self, McpError> {
        match value {
            CertificateIssuanceOutcome::Issued(value) => {
                let secret_file = if let Some(private_key) = &value.private_key {
                    disposition.stage(
                        CERTIFICATES_ISSUE_TOOL,
                        || serde_json::json!({ "privateKey": private_key.expose_secret() }),
                    )?
                } else {
                    None
                };
                Ok(Self {
                    outcome: CertificateIssueOutcomeKind::Issued,
                    project_id: value.project_id,
                    profile_id: value.profile_id,
                    request_id: value.request_id,
                    status: None,
                    certificate_id: Some(value.certificate_id),
                    serial_number: Some(value.serial_number),
                    certificate: Some(value.certificate),
                    issuing_ca_certificate: Some(value.issuing_ca_certificate),
                    certificate_chain: Some(value.certificate_chain),
                    private_key: secret_file.is_none().then_some(value.private_key).flatten(),
                    secret_file,
                })
            }
            CertificateIssuanceOutcome::Pending {
                project_id,
                profile_id,
                request_id,
                status,
            } => Ok(Self {
                outcome: CertificateIssueOutcomeKind::Pending,
                project_id,
                profile_id,
                request_id,
                status,
                certificate_id: None,
                serial_number: None,
                certificate: None,
                issuing_ca_certificate: None,
                certificate_chain: None,
                private_key: None,
                secret_file: None,
            }),
        }
    }
}

impl Serialize for CertificateIssueOutput {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: Serializer,
    {
        let mut output = serializer.serialize_struct("CertificateIssueOutput", 12)?;
        output.serialize_field("outcome", &self.outcome)?;
        output.serialize_field("projectId", &self.project_id)?;
        output.serialize_field("profileId", &self.profile_id)?;
        output.serialize_field("requestId", &self.request_id)?;
        if let Some(value) = self.status {
            output.serialize_field("status", &value)?;
        }
        if let Some(value) = &self.certificate_id {
            output.serialize_field("certificateId", value)?;
        }
        if let Some(value) = &self.serial_number {
            output.serialize_field("serialNumber", value)?;
        }
        if let Some(value) = &self.certificate {
            output.serialize_field("certificate", value)?;
        }
        if let Some(value) = &self.issuing_ca_certificate {
            output.serialize_field("issuingCaCertificate", value)?;
        }
        if let Some(value) = &self.certificate_chain {
            output.serialize_field("certificateChain", value)?;
        }
        if let Some(value) = &self.private_key {
            output.serialize_field("privateKey", value.expose_secret())?;
        }
        if let Some(value) = &self.secret_file {
            output.serialize_field("secretFile", value)?;
        }
        output.end()
    }
}

