#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct CertificatePolicyCreateInput {
    /// Canonical UUID of the Certificate Manager project that will own the policy.
    #[schemars(regex(
        pattern = r"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$"
    ))]
    project_id: String,
    /// Project-local lowercase policy name with single hyphen separators.
    #[schemars(
        length(min = 1, max = 255),
        regex(pattern = r"^[a-z0-9]+(?:-[a-z0-9]+)*$")
    )]
    name: String,
    /// Optional bounded policy description.
    #[schemars(length(max = 1000))]
    description: Option<String>,
    /// Optional unique subject-attribute rules.
    subject: Option<Vec<CertificatePolicySubjectRuleInput>>,
    /// Optional unique subject-alternative-name rules.
    sans: Option<Vec<CertificatePolicySanRuleInput>>,
    /// Optional key-usage policy.
    key_usages: Option<CertificatePolicyKeyUsageRuleInput>,
    /// Optional extended-key-usage policy.
    extended_key_usages: Option<CertificatePolicyExtendedKeyUsageRuleInput>,
    /// Optional signature and public-key algorithm policy.
    algorithms: Option<CertificatePolicyAlgorithmsInput>,
    /// Optional maximum certificate validity policy.
    validity: Option<CertificatePolicyValidityInput>,
    /// Optional certificate-authority basic-constraints policy.
    basic_constraints: Option<CertificatePolicyBasicConstraintsInput>,
    /// Must be true to authorize policy creation.
    confirm: bool,
}

impl CertificatePolicyCreateInput {
    fn into_parts(
        self,
    ) -> Result<
        (
            CertificateAuthorityProjectId,
            CertificatePolicyCreation,
            bool,
        ),
        McpError,
    > {
        let project_id =
            CertificateAuthorityProjectId::new(self.project_id).map_err(invalid_input)?;
        let creation = CertificatePolicyCreation::new(
            self.name,
            self.description,
            self.subject.map(|rules| {
                rules
                    .into_iter()
                    .map(CertificatePolicySubjectRuleInput::into_domain)
                    .collect()
            }),
            self.sans.map(|rules| {
                rules
                    .into_iter()
                    .map(CertificatePolicySanRuleInput::into_domain)
                    .collect()
            }),
            self.key_usages
                .map(CertificatePolicyKeyUsageRuleInput::into_domain),
            self.extended_key_usages
                .map(CertificatePolicyExtendedKeyUsageRuleInput::into_domain),
            self.algorithms.map(|algorithms| {
                CertificatePolicyAlgorithms::new(algorithms.signature, algorithms.key_algorithm)
            }),
            self.validity
                .map(|validity| {
                    CertificatePolicyMaxValidity::new(validity.max)
                        .map(|max| CertificatePolicyValidity::new(Some(max)))
                })
                .transpose()
                .map_err(invalid_input)?,
            self.basic_constraints.map(|constraints| {
                CertificatePolicyBasicConstraints::new(
                    constraints.is_ca,
                    constraints.max_path_length,
                )
            }),
        )
        .map_err(invalid_input)?;
        Ok((project_id, creation, self.confirm))
    }
}

fn nullable_policy_change<T>(
    value: Option<T>,
    clear: bool,
) -> Result<Option<CertificatePolicyFieldChange<T>>, McpError> {
    match (value, clear) {
        (Some(_), true) => Err(invalid_input(
            "replacement values cannot be combined with their clear flags",
        )),
        (Some(value), false) => Ok(Some(CertificatePolicyFieldChange::Set(value))),
        (None, true) => Ok(Some(CertificatePolicyFieldChange::Clear)),
        (None, false) => Ok(None),
    }
}

#[derive(Debug, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct CertificatePolicyUpdateInput {
    /// Exact project and certificate policy to update.
    target: CertificatePolicyTargetInput,
    /// Optional replacement project-local lowercase policy name.
    #[schemars(
        length(min = 1, max = 255),
        regex(pattern = r"^[a-z0-9]+(?:-[a-z0-9]+)*$")
    )]
    name: Option<String>,
    /// Optional replacement description.
    #[schemars(length(max = 1000))]
    description: Option<String>,
    /// Optional replacement subject rules.
    subject: Option<Vec<CertificatePolicySubjectRuleInput>>,
    /// Optional replacement subject-alternative-name rules.
    sans: Option<Vec<CertificatePolicySanRuleInput>>,
    /// Optional replacement key-usage policy.
    key_usages: Option<CertificatePolicyKeyUsageRuleInput>,
    /// Optional replacement extended-key-usage policy.
    extended_key_usages: Option<CertificatePolicyExtendedKeyUsageRuleInput>,
    /// Optional replacement algorithm policy.
    algorithms: Option<CertificatePolicyAlgorithmsInput>,
    /// Optional replacement maximum-validity policy.
    validity: Option<CertificatePolicyValidityInput>,
    /// Optional replacement basic-constraints policy.
    basic_constraints: Option<CertificatePolicyBasicConstraintsInput>,
    /// Clear the basic-constraints policy; cannot be combined with a replacement.
    #[serde(default)]
    clear_basic_constraints: bool,
    /// Must be true to apply the update.
    confirm: bool,
}

impl CertificatePolicyUpdateInput {
    fn into_parts(
        self,
    ) -> Result<
        (
            CertificateAuthorityProjectId,
            CertificatePolicyId,
            CertificatePolicyChange,
            bool,
        ),
        McpError,
    > {
        let (project_id, policy_id) = self.target.into_parts()?;
        let change = CertificatePolicyChange::new(
            self.name,
            self.description,
            self.subject.map(|rules| {
                rules
                    .into_iter()
                    .map(CertificatePolicySubjectRuleInput::into_domain)
                    .collect()
            }),
            self.sans.map(|rules| {
                rules
                    .into_iter()
                    .map(CertificatePolicySanRuleInput::into_domain)
                    .collect()
            }),
            self.key_usages
                .map(CertificatePolicyKeyUsageRuleInput::into_domain),
            self.extended_key_usages
                .map(CertificatePolicyExtendedKeyUsageRuleInput::into_domain),
            self.algorithms.map(|value| {
                CertificatePolicyAlgorithms::new(value.signature, value.key_algorithm)
            }),
            self.validity
                .map(|value| {
                    CertificatePolicyMaxValidity::new(value.max)
                        .map(|max| CertificatePolicyValidity::new(Some(max)))
                })
                .transpose()
                .map_err(invalid_input)?,
            nullable_policy_change(
                self.basic_constraints.map(|value| {
                    CertificatePolicyBasicConstraints::new(value.is_ca, value.max_path_length)
                }),
                self.clear_basic_constraints,
            )?,
        )
        .map_err(invalid_input)?;
        Ok((project_id, policy_id, change, self.confirm))
    }
}

