impl CertificateProfileEnrollmentChangeInput {
    fn into_domain(self) -> CertificateProfileEnrollmentChange {
        match self {
            Self::Api {
                auto_renew,
                renew_before_days,
            } => CertificateProfileEnrollmentChange::Api {
                auto_renew,
                renew_before_days,
            },
            Self::Est {
                disable_bootstrap_ca_validation,
                passphrase,
                ca_chain,
            } => CertificateProfileEnrollmentChange::Est {
                disable_bootstrap_ca_validation,
                passphrase,
                ca_chain,
            },
            Self::Acme {
                skip_dns_ownership_verification,
                skip_eab_binding,
            } => CertificateProfileEnrollmentChange::Acme(CertificateProfileAcmeChange {
                skip_dns_ownership_verification,
                skip_eab_binding,
            }),
            Self::Scep {
                challenge_type,
                challenge_password,
                include_ca_cert_in_response,
                allow_cert_based_renewal,
                dynamic_challenge_expiry_minutes,
                dynamic_challenge_max_pending,
            } => CertificateProfileEnrollmentChange::Scep {
                challenge_type,
                challenge_password,
                include_ca_cert_in_response,
                allow_cert_based_renewal,
                dynamic_challenge_expiry_minutes,
                dynamic_challenge_max_pending,
            },
        }
    }
}

