#[derive(Debug, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
// Three independent nullable fields need explicit clear intent in addition to confirmation.
#[allow(clippy::struct_excessive_bools)]
struct CertificateProfileUpdateInput {
    /// Exact project and certificate profile to update.
    target: CertificateProfileTargetInput,
    /// Optional replacement project-local slug.
    #[schemars(length(min = 1, max = 255), regex(pattern = r"^[a-z0-9-]+$"))]
    slug: Option<String>,
    /// Optional replacement description.
    #[schemars(length(max = 1000))]
    description: Option<String>,
    /// Clear the description; cannot be combined with a replacement.
    #[serde(default)]
    clear_description: bool,
    /// Optional same-family enrollment configuration change.
    enrollment: Option<CertificateProfileEnrollmentChangeInput>,
    /// Optional replacement provider-specific configuration.
    external_config: Option<CertificateProfileExternalConfigInput>,
    /// Clear provider-specific configuration; cannot be combined with a replacement.
    #[serde(default)]
    clear_external_config: bool,
    /// Optional replacement profile defaults.
    defaults: Option<CertificateProfileDefaultsInput>,
    /// Clear all profile defaults; cannot be combined with a replacement.
    #[serde(default)]
    clear_defaults: bool,
    /// Must be true to apply the update.
    confirm: bool,
}

impl CertificateProfileUpdateInput {
    fn into_parts(
        self,
    ) -> Result<
        (
            CertificateAuthorityProjectId,
            CertificateProfileId,
            CertificateProfileChange,
            bool,
        ),
        McpError,
    > {
        if (self.clear_description && self.description.is_some())
            || (self.clear_external_config && self.external_config.is_some())
            || (self.clear_defaults && self.defaults.is_some())
        {
            return Err(invalid_input(
                "replacement values cannot be combined with their clear flags",
            ));
        }
        let (project_id, profile_id) = self.target.into_parts()?;
        let description = if self.clear_description {
            Some(CertificateProfileDescriptionChange::Clear)
        } else {
            self.description
                .map(CertificateProfileDescriptionChange::Set)
        };
        let external_configs = if self.clear_external_config {
            Some(CertificateProfileExternalConfigChange::Clear)
        } else {
            self.external_config
                .map(CertificateProfileExternalConfigInput::into_domain)
                .transpose()?
                .map(CertificateProfileExternalConfigChange::Set)
        };
        let defaults = if self.clear_defaults {
            Some(CertificateProfileDefaultsChange::Clear)
        } else {
            self.defaults
                .map(CertificateProfileDefaultsInput::into_domain)
                .transpose()?
                .map(Box::new)
                .map(CertificateProfileDefaultsChange::Set)
        };
        let change = CertificateProfileChange::new(
            self.slug
                .map(CertificateProfileSlug::new)
                .transpose()
                .map_err(invalid_input)?,
            description,
            self.enrollment
                .map(CertificateProfileEnrollmentChangeInput::into_domain),
            external_configs,
            defaults,
        )
        .map_err(invalid_input)?;
        Ok((project_id, profile_id, change, self.confirm))
    }
}

