#[derive(Debug, JsonSchema)]
#[schemars(rename_all = "camelCase")]
struct CertificateProfileBundleOutput {
    profile_id: String,
    certificate: String,
    certificate_chain: String,
    /// Explicitly revealed PEM private key, present only for inline delivery. This field
    /// is sensitive.
    #[schemars(with = "Option<String>")]
    private_key: Option<SecretValue>,
    /// Out-of-context reference to the private key, present only for reference delivery.
    /// The envelope's data carries a privateKey field.
    secret_file: Option<SecretFileReference>,
    serial_number: String,
}

impl CertificateProfileBundleOutput {
    fn deliver(
        value: CertificateProfileBundle,
        disposition: SecretDisposition<'_>,
    ) -> Result<Self, McpError> {
        let secret_file = disposition.stage(
            CERTIFICATE_PROFILE_LATEST_BUNDLE_REVEAL_TOOL,
            || serde_json::json!({ "privateKey": value.private_key.expose_secret() }),
        )?;
        Ok(Self {
            profile_id: value.profile_id,
            certificate: value.certificate,
            certificate_chain: value.certificate_chain,
            private_key: secret_file.is_none().then_some(value.private_key),
            secret_file,
            serial_number: value.serial_number,
        })
    }
}

impl Serialize for CertificateProfileBundleOutput {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: Serializer,
    {
        let mut output = serializer.serialize_struct("CertificateProfileBundleOutput", 5)?;
        output.serialize_field("profileId", &self.profile_id)?;
        output.serialize_field("certificate", &self.certificate)?;
        output.serialize_field("certificateChain", &self.certificate_chain)?;
        if let Some(value) = &self.private_key {
            output.serialize_field("privateKey", value.expose_secret())?;
        }
        if let Some(file) = &self.secret_file {
            output.serialize_field("secretFile", file)?;
        }
        output.serialize_field("serialNumber", &self.serial_number)?;
        output.end()
    }
}

