struct KmsBulkPrivateKeysOutput {
    /// Opaque project identifier validated for every returned key.
    project_id: String,
    /// Exact bounded set of revealed keys; their private material is inline only for
    /// inline delivery.
    keys: Vec<KmsBulkPrivateKeyOutput>,
    /// Out-of-context reference to every revealed private key, present only for
    /// reference delivery. The envelope's data carries a keys array of keyId, name, and
    /// privateKey fields.
    #[serde(skip_serializing_if = "Option::is_none")]
    secret_file: Option<SecretFileReference>,
}

impl KmsBulkPrivateKeysOutput {
    fn deliver(
        project_id: String,
        keys: Vec<KmsBulkPrivateKey>,
        disposition: SecretDisposition<'_>,
    ) -> Result<Self, McpError> {
        let secret_file = disposition.stage(KMS_PRIVATE_KEYS_BULK_REVEAL_TOOL, || {
            serde_json::json!({
                "keys": keys
                    .iter()
                    .map(|key| {
                        serde_json::json!({
                            "keyId": key.key_id,
                            "name": key.name,
                            "privateKey": key.private_key.expose_secret(),
                        })
                    })
                    .collect::<Vec<_>>(),
            })
        })?;
        let inline = secret_file.is_none();
        Ok(Self {
            project_id,
            keys: keys
                .into_iter()
                .map(|key| KmsBulkPrivateKeyOutput {
                    key_id: key.key_id,
                    name: key.name,
                    key_usage: key.key_usage,
                    algorithm: key.algorithm,
                    private_key: inline.then_some(key.private_key),
                    public_key: key.public_key,
                })
                .collect(),
            secret_file,
        })
    }
}

fn deserialize_secret_input<'de, D>(deserializer: D) -> Result<SecretValue, D::Error>
where
    D: serde::Deserializer<'de>,
{
    String::deserialize(deserializer).map(SecretValue::new)
}

fn deserialize_optional_secret_input<'de, D>(
    deserializer: D,
) -> Result<Option<SecretValue>, D::Error>
where
    D: serde::Deserializer<'de>,
{
    Option::<String>::deserialize(deserializer).map(|value| value.map(SecretValue::new))
}

/// How a reveal-class operation delivers its secret material.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase")]
enum SecretDeliveryMode {
    /// Stage an out-of-context envelope and return an opaque secretFile reference.
    Reference,
    /// Place the value in the tool result, and therefore in the caller's context.
    InlineValue,
}

/// The delivery a request resolved to, fixed before any upstream call so a delivery
/// refusal cannot burn a recorded or one-shot operation. Reference delivery holds a
/// reserved staging slot for the same reason: capacity is decided here, and the later
/// stage cannot fail after a one-shot upstream operation has completed.
enum SecretDisposition<'a> {
    Inline,
    Reference(StageSlot<'a>),
}

fn resolve_delivery(
    files: Option<&SecretFilePlane>,
    requested: Option<SecretDeliveryMode>,
) -> Result<SecretDisposition<'_>, McpError> {
    match (files, requested) {
        (Some(plane), None | Some(SecretDeliveryMode::Reference)) => plane
            .reserve()
            .map(SecretDisposition::Reference)
            .map_err(|error| McpError::internal_error(error.to_string(), None)),
        (Some(_) | None, Some(SecretDeliveryMode::InlineValue)) | (None, None) => {
            Ok(SecretDisposition::Inline)
        }
        (None, Some(SecretDeliveryMode::Reference)) => Err(McpError::invalid_params(
            "delivery \"reference\" requires the reveal transfer plane, which this deployment \
             does not configure; omit delivery to receive the value inline",
            None,
        )),
    }
}

impl SecretDisposition<'_> {
    /// Stage the operation's sensitive fields, exactly as they would have appeared
    /// inline, and return the reference the tool result carries instead.
    ///
    /// `None` means inline delivery: the caller keeps its value fields. The sensitive
    /// fields are built lazily, only on the reference path, so an inline reveal never
    /// creates a plaintext copy outside its redacting values; the envelope path
    /// zeroizes what it builds. Consumes the disposition because a reserved slot
    /// stages exactly once, and the upstream operation this runs after may have been
    /// one-shot: nothing on this path is allowed to refuse the material it carries.
    fn stage(
        self,
        operation: &str,
        data: impl FnOnce() -> Value,
    ) -> Result<Option<SecretFileReference>, McpError> {
        let SecretDisposition::Reference(slot) = self else {
            return Ok(None);
        };
        let envelope = secret_envelope(operation, data())
            .map_err(|_| McpError::internal_error("serialize the secret envelope", None))?;
        Ok(Some(slot.stage(operation, envelope)))
    }
}

/// A reference to one uploaded secret value, accepted as a bare URI string or as a
/// SEP-2631 `FileValue` object. Both forms appear on the wire: the interoperable form
/// is the string, and a file-aware intermediary may deliver the object form with
/// metadata members it validated.
#[derive(Debug)]
struct SecretFileInput {
    uri: String,
}

impl<'de> Deserialize<'de> for SecretFileInput {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: serde::Deserializer<'de>,
    {
        struct InputVisitor;
        impl<'de> serde::de::Visitor<'de> for InputVisitor {
            type Value = SecretFileInput;

            fn expecting(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
                formatter.write_str("a file reference URI string or a FileValue object")
            }

            fn visit_str<E: serde::de::Error>(self, value: &str) -> Result<Self::Value, E> {
                Ok(SecretFileInput {
                    uri: value.to_owned(),
                })
            }

            fn visit_map<A: serde::de::MapAccess<'de>>(
                self,
                mut map: A,
            ) -> Result<Self::Value, A::Error> {
                let mut uri = None;
                while let Some(key) = map.next_key::<String>()? {
                    if key == "uri" {
                        uri = Some(map.next_value::<String>()?);
                    } else {
                        map.next_value::<serde::de::IgnoredAny>()?;
                    }
                }
                uri.map(|uri| SecretFileInput { uri })
                    .ok_or_else(|| serde::de::Error::missing_field("uri"))
            }
        }
        deserializer.deserialize_any(InputVisitor)
    }
}

impl JsonSchema for SecretFileInput {
    fn schema_name() -> std::borrow::Cow<'static, str> {
        "SecretFileInput".into()
    }

    fn json_schema(_: &mut schemars::SchemaGenerator) -> schemars::Schema {
        secret_file_input_schema()
    }
}

/// The published schema for a file-referenced secret value, carrying the `x-mcp-file`
/// annotation a file-aware intermediary uses to deliver uploaded bytes.
fn secret_file_input_schema() -> schemars::Schema {
    schemars::json_schema!({
        "description": "Out-of-context reference to an uploaded secret value: an                         mcp-file URI string, or a FileValue object carrying one.",
        "anyOf": [
            { "type": "string" },
            {
                "type": "object",
                "properties": { "uri": { "type": "string" } },
                "required": ["uri"]
            }
        ],
        "x-mcp-file": { "transferModes": ["upload"], "maxSize": crate::files::MAX_UPLOAD_BYTES }
    })
}

/// Minimal upload annotation used by the generic write executor schema.
///
/// `operations.describe` publishes each operation's complete field schema. The
/// executor only needs to expose the annotations that a file-aware intermediary
/// evaluates before it can populate the otherwise open `arguments` object.
fn secret_file_annotation_schema() -> schemars::Schema {
    schemars::json_schema!({
        "anyOf": [
            {"type": "string"},
            {
                "type": "object",
                "properties": {"uri": {"type": "string"}},
                "required": ["uri"]
            }
        ],
        "x-mcp-file": { "transferModes": ["upload"], "maxSize": crate::files::MAX_UPLOAD_BYTES }
    })
}

/// Resolve a write-class secret value from exactly one of its two sources.
///
/// The uploaded bytes are consumed single-use and move directly into the redacting
/// value type; a reference is refused, not dereferenced, when it is not one this
/// server's plane received.
fn resolve_secret_value(
    files: Option<&SecretFilePlane>,
    inline: Option<SecretValue>,
    file: Option<SecretFileInput>,
) -> Result<SecretValue, McpError> {
    match (inline, file) {
        (Some(value), None) => Ok(value),
        (None, Some(reference)) => {
            let Some(plane) = files else {
                return Err(McpError::invalid_params(
                    "secretValueFile requires the transfer plane, which this deployment does                      not configure; send secretValue instead",
                    None,
                ));
            };
            let bytes = plane.take_received(&reference.uri).ok_or_else(|| {
                McpError::invalid_params("no uploaded secret value matches that reference", None)
            })?;
            let text = std::str::from_utf8(&bytes).map_err(|_| {
                McpError::invalid_params("an uploaded secret value must be UTF-8 text", None)
            })?;
            Ok(SecretValue::new(text))
        }
        _ => Err(McpError::invalid_params(
            "provide exactly one of secretValue and secretValueFile",
            None,
        )),
    }
}

/// Consume one uploaded UTF-8 value into the redacting domain type.
fn resolve_uploaded_secret(
    files: Option<&SecretFilePlane>,
    reference: &SecretFileInput,
    field: &str,
) -> Result<SecretValue, McpError> {
    let Some(plane) = files else {
        return Err(McpError::invalid_params(
            format!("{field} requires the upload transfer plane configured by this deployment"),
            None,
        ));
    };
    let bytes = plane.take_received(&reference.uri).ok_or_else(|| {
        McpError::invalid_params(format!("no uploaded value matches {field}"), None)
    })?;
    let text = std::str::from_utf8(&bytes)
        .map_err(|_| McpError::invalid_params(format!("{field} must contain UTF-8 text"), None))?;
    Ok(SecretValue::new(text))
}

/// Serve one fallible upstream result whose success is shaped by delivery mode.
///
/// Mirrors [`tool_result`], with a fallible builder: an upstream failure stays a
/// recoverable tool error, while a staging failure is a protocol error.
fn delivered_result<T, E, O, F>(result: Result<T, E>, build: F) -> Result<CallToolResult, McpError>
where
    E: Display,
    O: Serialize,
    F: FnOnce(T) -> Result<O, McpError>,
{
    match result {
        Ok(value) => structured(build(value)?),
        Err(error) => Ok(CallToolResult::error(vec![ContentBlock::text(
            error.to_string(),
        )])),
    }
}

