/// The tools a client sees: local discovery plus one executor per tier.
///
/// The typed operations are not published individually. Their schemas are
/// charged against a caller's context before its first message, and the whole
/// set is larger than the window most callers have, while any one turn uses one
/// or two of them. Callers discover names through `operations.list` and fetch
/// one schema through `operations.describe` before using its executor.
pub(crate) fn catalog() -> ListToolsResult {
    let mut tools = vec![
        read_tool::<EmptyInput, ServerInfoOutput>(
            SERVER_INFO_TOOL,
            "Report build, schema revision, MCP protocol, and active transport locally. \
             Use server.capabilities for deployment limits and compiled support.",
            false,
        )
        .tool,
        read_tool::<EmptyInput, ServerCapabilitiesOutput>(
            SERVER_CAPABILITIES_TOOL,
            "Report compiled capabilities, unavailable reasons, and this instance's delivery and \
             limit settings. Answers locally; upstream permission and license entitlement are not probed.",
            false,
        )
        .tool,
        read_tool::<OperationsListInput, OperationsListOutput>(
            OPERATIONS_LIST_TOOL,
            "Find an operation by intent, tier, or name prefix. Returns a bounded page and \
             nextOffset; retain filters when continuing. Fetch schemas with operations.describe.",
            false,
        )
        .tool,
        read_tool::<OperationsDescribeInput, OperationsDescribeOutput>(
            OPERATIONS_DESCRIBE_TOOL,
            "Get one operation's executor, availability, and schemas. Set includeOutputSchema \
             false for input only. Pass values matching inputSchema as executor arguments.",
            false,
        )
        .tool,
        read_tool::<TypeDescribeInput, TypeDescribeOutput>(
            TYPES_DESCRIBE_TOOL,
            "Get a resource's data model, such as a project, a secret's metadata, or a dynamic secret. \
             Use operations.describe for a call's arguments and result.",
            false,
        )
        .tool,
    ];
    tools.extend(executor_tools());

    ListToolsResult {
        tools,
        next_cursor: None,
        meta: None,
    }
}

/// Look up the tier an operation was declared at.
///
/// Returns `None` for a name this build does not serve, so a caller must
/// decide what an unknown operation means rather than receiving a default that
/// understates it.
pub(crate) fn tool_tier(name: &str) -> Option<ToolTier> {
    static TIERS: OnceLock<HashMap<String, ToolTier>> = OnceLock::new();

    TIERS
        .get_or_init(|| {
            operation_catalog()
                .into_iter()
                .map(|tiered| (tiered.tool.name.to_string(), tiered.tier))
                .collect()
        })
        .get(name)
        .copied()
}

/// The typed operations an executor can reach, with their tiers.
///
/// These are served by dispatch and described by `operations.describe`, but are
/// no longer listed as individual tools.
#[cfg(test)]
pub(crate) fn operations() -> Vec<TieredTool> {
    operation_catalog()
}

/// The typed operations, which dispatch serves but the catalog no longer lists.
fn operation_catalog() -> Vec<TieredTool> {
    let mut tools = discovery_tools().into_iter().collect::<Vec<_>>();
    tools.extend(project_environment_tools());
    tools.extend(folder_tag_tools());
    tools.extend(identity_tools());
    tools.extend(project_membership_tools());
    tools.extend(role_tools());
    tools.extend(group_tools());
    tools.extend(identity_project_additional_privilege_tools());
    tools.extend(universal_auth_tools());
    tools.extend(token_auth_tools());
    tools.extend(kubernetes_auth_tools());
    tools.extend(secret_tools());
    tools.extend(secret_import_tools());
    tools.extend(audit_log_tools());
    tools.extend(app_automation_tools());
    tools.extend(sql_secret_rotation_tools());
    tools.extend(certificate_authority_tools());
    tools.extend(certificate_tools());
    tools.extend(certificate_policy_tools());
    tools.extend(certificate_profile_tools());
    tools.extend(ssh_certificate_authority_tools());
    tools.extend(code_signer_tools());
    tools.extend(kms_tools());
    tools.extend(dynamic_secret_tools());
    tools.extend(ssh_host_tools());
    tools
}

