async fn dispatch_certificate_material_workflow(
    client: &InfisicalClient,
    files: Option<&SecretFilePlane>,
    params: &mut CallToolRequestParams,
) -> Result<CallToolResult, McpError> {
    match params.name.as_ref() {
        CERTIFICATES_IMPORT_TOOL => {
            let input = parse_arguments::<CertificateImportInput>(
                params,
                "certificates.import arguments do not match the declared schema",
            )?;
            if !input.confirm {
                return Err(McpError::invalid_params(
                    "confirm must be true before uploaded certificate material is consumed",
                    None,
                ));
            }
            let (project_id, certificate_import) = input.into_parts(files)?;
            tool_result(
                client
                    .import_certificate(&project_id, certificate_import, true)
                    .await,
            )
        }
        CERTIFICATES_CERTIFICATE_GET_TOOL => {
            let input = parse_arguments::<CertificateTargetInput>(
                params,
                "certificates.certificate.get arguments do not match the declared schema",
            )?;
            let (project_id, certificate_id) = input.into_parts()?;
            tool_result(
                client
                    .get_certificate_public_material(&project_id, &certificate_id)
                    .await,
            )
        }
        CERTIFICATES_BUNDLE_REVEAL_TOOL => {
            let input = parse_arguments::<CertificateMaterialRevealInput>(
                params,
                "certificates.bundle.reveal arguments do not match the declared schema",
            )?;
            let disposition = resolve_delivery(files, input.delivery)?;
            let (project_id, certificate_id) = input.target.into_parts()?;
            delivered_result(
                client
                    .reveal_certificate_bundle(&project_id, &certificate_id, input.confirm_reveal)
                    .await,
                |bundle| CertificateBundleOutput::deliver(bundle, disposition),
            )
        }
        CERTIFICATES_PRIVATE_KEY_REVEAL_TOOL => {
            let input = parse_arguments::<CertificateMaterialRevealInput>(
                params,
                "certificates.privateKey.reveal arguments do not match the declared schema",
            )?;
            let disposition = resolve_delivery(files, input.delivery)?;
            let (project_id, certificate_id) = input.target.into_parts()?;
            delivered_result(
                client
                    .reveal_certificate_private_key(
                        &project_id,
                        &certificate_id,
                        input.confirm_reveal,
                    )
                    .await,
                |private_key| CertificatePrivateKeyOutput::deliver(private_key, disposition),
            )
        }
        _ => Err(McpError::method_not_found::<
            rmcp::model::CallToolRequestMethod,
        >()),
    }
}

