fn is_access_control_tool(name: &str) -> bool {
    is_role_tool(name) || is_group_tool(name) || is_identity_project_additional_privilege_tool(name)
}

async fn dispatch_access_control_workflow(
    client: &InfisicalClient,
    params: &mut CallToolRequestParams,
) -> Result<CallToolResult, McpError> {
    if is_role_tool(params.name.as_ref()) {
        dispatch_role_workflow(client, params).await
    } else if is_group_tool(params.name.as_ref()) {
        dispatch_group_workflow(client, params).await
    } else {
        dispatch_identity_project_additional_privilege_workflow(client, params).await
    }
}

