async fn dispatch_secret_workflow(
    client: &InfisicalClient,
    files: Option<&SecretFilePlane>,
    params: &mut CallToolRequestParams,
) -> Result<CallToolResult, McpError> {
    match params.name.as_ref() {
        SECRET_REVEAL_TOOL => {
            let input = parse_arguments::<SecretTargetOnlyInput>(
                params,
                "secrets.reveal arguments do not match the declared schema",
            )?;
            let disposition = resolve_delivery(files, input.delivery)?;
            let (scope, name) = input.target.into_parts()?;
            delivered_result(client.reveal_secret(&scope, &name).await, |secret| {
                SecretRevealOutput::deliver(secret, disposition)
            })
        }
        SECRET_CREATE_TOOL => {
            let input = parse_arguments::<SecretValueMutationInput>(
                params,
                "secrets.create arguments do not match the declared schema",
            )?;
            let (scope, name, value) = input.into_parts(files)?;
            tool_result(client.create_secret(&scope, &name, value).await)
        }
        SECRET_UPDATE_TOOL => {
            let input = parse_arguments::<SecretValueMutationInput>(
                params,
                "secrets.update arguments do not match the declared schema",
            )?;
            let (scope, name, value) = input.into_parts(files)?;
            tool_result(client.update_secret(&scope, &name, value).await)
        }
        SECRET_DELETE_TOOL => {
            let input = parse_arguments::<SecretDeleteInput>(
                params,
                "secrets.delete arguments do not match the declared schema",
            )?;
            let (scope, name) = input.into_confirmed_parts()?;
            tool_result(client.delete_secret(&scope, &name, true).await)
        }
        SECRET_BATCH_CREATE_TOOL => {
            let input = parse_arguments::<SecretBatchValueMutationInput>(
                params,
                "secrets.batch.create arguments do not match the declared schema",
            )?;
            let (scope, secrets) = input.into_parts()?;
            tool_result(client.create_secrets_batch(&scope, secrets).await)
        }
        SECRET_BATCH_UPDATE_TOOL => {
            let input = parse_arguments::<SecretBatchValueMutationInput>(
                params,
                "secrets.batch.update arguments do not match the declared schema",
            )?;
            let (scope, secrets) = input.into_parts()?;
            tool_result(client.update_secrets_batch(&scope, secrets).await)
        }
        SECRET_BATCH_DELETE_TOOL => {
            let input = parse_arguments::<SecretBatchDeleteInput>(
                params,
                "secrets.batch.delete arguments do not match the declared schema",
            )?;
            let (scope, names) = input.into_confirmed_parts()?;
            tool_result(client.delete_secrets_batch(&scope, names, true).await)
        }
        _ => dispatch_secret_import_workflow(client, params).await,
    }
}

