fn available(name: &'static str) -> Capability {
    Capability {
        name,
        available: true,
        reason: None,
    }
}

fn unavailable(name: &'static str, reason: &'static str) -> Capability {
    Capability {
        name,
        available: false,
        reason: Some(reason),
    }
}

fn parse_arguments<T>(
    params: &mut CallToolRequestParams,
    message: &'static str,
) -> Result<T, McpError>
where
    T: DeserializeOwned,
{
    // Transfer ownership so secret deserializers receive the original strings
    // instead of leaving ordinary-string duplicates in the request map.
    let arguments = params
        .arguments
        .take()
        .map_or_else(|| Value::Object(Map::new()), Value::Object);
    serde_json::from_value(arguments).map_err(|_| McpError::invalid_params(message, None))
}

fn invalid_input(error: impl Display) -> McpError {
    McpError::invalid_params(error.to_string(), None)
}

fn tool_result<T, E>(result: Result<T, E>) -> Result<CallToolResult, McpError>
where
    T: Serialize,
    E: Display,
{
    match result {
        Ok(output) => structured(output),
        Err(error) => Ok(CallToolResult::error(vec![ContentBlock::text(
            error.to_string(),
        )])),
    }
}

fn structured<T: Serialize>(output: T) -> Result<CallToolResult, McpError> {
    let value = serde_json::to_value(output)
        .map_err(|_| McpError::internal_error("serialize tool result", None))?;
    Ok(CallToolResult::structured(value))
}

pub(crate) fn schema_object<T: JsonSchema>() -> Map<String, Value> {
    match schema_value::<T>() {
        Value::Object(object) => object,
        _ => unreachable!("a root JSON schema is an object"),
    }
}

fn schema_value<T: JsonSchema>() -> Value {
    let mut schema =
        serde_json::to_value(schema_for!(T)).expect("Rust-derived schema must serialize");
    normalize_type_unions(&mut schema);
    schema
}

/// Express legal array-valued JSON Schema type unions in the object form that
/// strict MCP clients consistently consume, without changing the accepted
/// value set or confusing nullable values with optional fields.
fn normalize_type_unions(schema: &mut Value) {
    let Some(object) = schema.as_object_mut() else {
        return;
    };

    let portable_types = object.get("type").and_then(|value| {
        let values = value.as_array()?;
        let mut types: Vec<String> = Vec::with_capacity(values.len());
        for value in values {
            let name = value.as_str()?;
            if !JSON_SCHEMA_TYPES.contains(&name) || types.iter().any(|item| item == name) {
                return None;
            }
            types.push(name.to_owned());
        }
        (!types.is_empty()).then_some(types)
    });
    if let Some(types) = portable_types {
        object.remove("type");
        let branches = Value::Array(
            types
                .into_iter()
                .map(|name| serde_json::json!({"type": name}))
                .collect(),
        );
        if object.contains_key("anyOf") {
            object
                .entry("allOf")
                .or_insert_with(|| Value::Array(Vec::new()))
                .as_array_mut()
                .expect("a generated allOf schema must be an array")
                .push(serde_json::json!({"anyOf": branches}));
        } else {
            object.insert("anyOf".to_owned(), branches);
        }
    }

    for keyword in [
        "$defs",
        "definitions",
        "properties",
        "patternProperties",
        "dependentSchemas",
        "dependencies",
    ] {
        if let Some(children) = object.get_mut(keyword).and_then(Value::as_object_mut) {
            for child in children.values_mut() {
                normalize_type_unions(child);
            }
        }
    }
    for keyword in ["allOf", "anyOf", "oneOf", "prefixItems"] {
        if let Some(children) = object.get_mut(keyword).and_then(Value::as_array_mut) {
            for child in children {
                normalize_type_unions(child);
            }
        }
    }
    if let Some(items) = object.get_mut("items") {
        if let Some(children) = items.as_array_mut() {
            for child in children {
                normalize_type_unions(child);
            }
        } else {
            normalize_type_unions(items);
        }
    }
    for keyword in [
        "contains",
        "propertyNames",
        "not",
        "if",
        "then",
        "else",
        "contentSchema",
        "additionalProperties",
        "unevaluatedProperties",
        "additionalItems",
        "unevaluatedItems",
    ] {
        if let Some(child @ Value::Object(_)) = object.get_mut(keyword) {
            normalize_type_unions(child);
        }
    }
}

const JSON_SCHEMA_TYPES: [&str; 7] = [
    "null", "boolean", "object", "array", "number", "string", "integer",
];

#[cfg(test)]
mod schema_portability_tests {
    use std::collections::HashSet;

    use super::*;

    const BOOLEAN_SCHEMA_KEYWORDS: [&str; 4] = [
        "additionalProperties",
        "unevaluatedProperties",
        "additionalItems",
        "unevaluatedItems",
    ];
    const CONSTRAINING_KEYWORDS: [&str; 43] = [
        "type",
        "enum",
        "const",
        "multipleOf",
        "maximum",
        "exclusiveMaximum",
        "minimum",
        "exclusiveMinimum",
        "maxLength",
        "minLength",
        "pattern",
        "format",
        "contentMediaType",
        "contentEncoding",
        "contentSchema",
        "maxItems",
        "minItems",
        "uniqueItems",
        "maxContains",
        "minContains",
        "maxProperties",
        "minProperties",
        "required",
        "dependentRequired",
        "allOf",
        "anyOf",
        "oneOf",
        "not",
        "items",
        "prefixItems",
        "contains",
        "additionalItems",
        "unevaluatedItems",
        "properties",
        "patternProperties",
        "additionalProperties",
        "unevaluatedProperties",
        "propertyNames",
        "dependentSchemas",
        "dependencies",
        "$ref",
        "$dynamicRef",
        "$recursiveRef",
    ];

    fn for_each_subschema(node: &Map<String, Value>, mut visit: impl FnMut(&Value, &str)) {
        for keyword in [
            "properties",
            "patternProperties",
            "dependentSchemas",
            "dependencies",
            "$defs",
            "definitions",
        ] {
            if let Some(children) = node.get(keyword).and_then(Value::as_object) {
                for child in children.values() {
                    visit(child, keyword);
                }
            }
        }
        for keyword in ["allOf", "anyOf", "oneOf", "prefixItems"] {
            if let Some(children) = node.get(keyword).and_then(Value::as_array) {
                for child in children {
                    visit(child, keyword);
                }
            }
        }
        for keyword in [
            "items",
            "contains",
            "not",
            "propertyNames",
            "if",
            "then",
            "else",
            "additionalProperties",
            "unevaluatedProperties",
            "additionalItems",
            "unevaluatedItems",
            "contentSchema",
        ] {
            let Some(child) = node.get(keyword) else {
                continue;
            };
            if keyword == "items"
                && let Some(children) = child.as_array()
            {
                for child in children {
                    visit(child, keyword);
                }
                continue;
            }
            visit(child, keyword);
        }
    }

    fn schema_declares_id(schema: &Value, depth: usize) -> bool {
        if depth > 64 {
            return false;
        }
        let Some(node) = schema.as_object() else {
            return false;
        };
        if node
            .get("$id")
            .and_then(Value::as_str)
            .is_some_and(|id| !id.is_empty())
        {
            return true;
        }
        let mut found = false;
        for_each_subschema(node, |child, _| {
            found |= schema_declares_id(child, depth + 1);
        });
        found
    }

    fn inspector_findings(schema: &Value) -> Vec<&'static str> {
        fn walk(
            schema: &Value,
            parent_keyword: Option<&str>,
            depth: usize,
            has_embedded_ids: bool,
            findings: &mut Vec<&'static str>,
        ) {
            if depth > 64 {
                return;
            }
            if schema.is_boolean() {
                if parent_keyword.is_none_or(|keyword| !BOOLEAN_SCHEMA_KEYWORDS.contains(&keyword))
                {
                    findings.push("boolean-schema");
                }
                return;
            }
            let Some(node) = schema.as_object() else {
                return;
            };
            if node
                .get("type")
                .and_then(Value::as_array)
                .is_some_and(|types| {
                    !types.is_empty()
                        && types.iter().all(|item| {
                            item.as_str()
                                .is_some_and(|name| JSON_SCHEMA_TYPES.contains(&name))
                        })
                        && types
                            .iter()
                            .filter_map(Value::as_str)
                            .collect::<HashSet<_>>()
                            .len()
                            == types.len()
                })
            {
                findings.push("type-union");
            }
            if !has_embedded_ids
                && node
                    .get("$ref")
                    .and_then(Value::as_str)
                    .is_some_and(|reference| !reference.is_empty() && !reference.starts_with('#'))
            {
                findings.push("remote-ref");
            }
            let constrains = node
                .keys()
                .any(|keyword| CONSTRAINING_KEYWORDS.contains(&keyword.as_str()))
                || (node.contains_key("if")
                    && (node.contains_key("then") || node.contains_key("else")));
            if !constrains && parent_keyword != Some("not") {
                findings.push("untyped-schema");
            }
            for_each_subschema(node, |child, keyword| {
                walk(child, Some(keyword), depth + 1, has_embedded_ids, findings);
            });
        }

        let has_embedded_ids = schema_declares_id(schema, 0);
        let mut findings = Vec::new();
        walk(schema, None, 0, has_embedded_ids, &mut findings);
        findings
    }

    #[test]
    fn catalog_schemas_pass_mcp_inspector_portability_rules() {
        let mut findings = Vec::new();
        for tool in catalog().tools {
            for (kind, schema) in [
                ("inputSchema", Value::Object((*tool.input_schema).clone())),
                (
                    "outputSchema",
                    Value::Object((*tool.output_schema.expect("output schema")).clone()),
                ),
            ] {
                for rule in inspector_findings(&schema) {
                    findings.push(format!("{}.{}: {rule}", tool.name, kind));
                }
            }
        }
        assert!(findings.is_empty(), "{findings:#?}");
    }

    fn published_schema(tool_name: &str, output: bool) -> Value {
        let tool = catalog()
            .tools
            .into_iter()
            .find(|tool| tool.name == tool_name)
            .unwrap_or_else(|| panic!("{tool_name} is published"));
        if output {
            Value::Object((*tool.output_schema.expect("output schema")).clone())
        } else {
            Value::Object((*tool.input_schema).clone())
        }
    }

    fn validates(schema: &Value, instance: &Value) -> bool {
        jsonschema::validator_for(schema)
            .expect("published schema compiles")
            .is_valid(instance)
    }

    #[test]
    fn nullable_and_schema_document_runtime_shapes_remain_valid() {
        let operations_input = published_schema(OPERATIONS_LIST_TOOL, false);
        assert!(validates(
            &operations_input,
            &serde_json::json!({"tier": null, "namePrefix": null})
        ));

        let capabilities = published_schema(SERVER_CAPABILITIES_TOOL, true);
        assert!(validates(
            &capabilities,
            &serde_json::json!({
                "targetInfisicalVersion": "0.150.0",
                "schemaRevision": crate::runtime::SCHEMA_REVISION,
                "capabilities": [
                    {"name": "available", "available": true},
                    {"name": "unavailable", "available": false, "reason": "not served"}
                ]
            })
        ));

        let operation_description = published_schema(OPERATIONS_DESCRIBE_TOOL, true);
        assert!(validates(
            &operation_description,
            &serde_json::json!({
                "name": "projects.list",
                "executor": "infisical.read",
                "tier": "read",
                "description": "List projects",
                "availability": {
                    "implemented": true,
                    "enabledHere": true,
                    "requiresFileTransfer": false,
                    "upstreamAccess": "notProbed"
                },
                "inputSchema": {"type": "object"},
                "outputSchema": {"type": "object"}
            })
        ));

        let type_description = published_schema(TYPES_DESCRIBE_TOOL, true);
        assert!(validates(
            &type_description,
            &serde_json::json!({
                "typeName": "project",
                "schema": {"type": "object"}
            })
        ));
    }

    #[test]
    fn write_executor_file_annotations_publish_the_runtime_value_domain() {
        let write = published_schema(INFISICAL_WRITE_TOOL, false);
        let operation = "secrets.create";
        let file = &write["$defs"]["file"];
        assert!(file.get("x-mcp-file").is_some());
        assert!(validates(
            &write,
            &serde_json::json!({
                "operation": operation,
                "arguments": {"secretValueFile": "mcp-file://gateway/example"}
            })
        ));
        assert!(validates(
            &write,
            &serde_json::json!({
                "operation": operation,
                "arguments": {
                    "secretValueFile": {"uri": "mcp-file://gateway/example"}
                }
            })
        ));
        assert!(!validates(
            &write,
            &serde_json::json!({
                "operation": operation,
                "arguments": {"secretValueFile": 42}
            })
        ));
    }
}

