    fn assert_unknown_field_rejected<T>(name: &'static str, arguments: &Value)
    where
        T: DeserializeOwned,
    {
        let Err(error) = parse_arguments::<T>(
            &mut request(name, arguments),
            "paginated tool arguments must reject unknown fields",
        ) else {
            panic!("misspelled pagination field must be rejected");
        };
        assert_eq!(error.code, rmcp::model::ErrorCode::INVALID_PARAMS);
    }

