    #[test]
    fn github_app_automation_inputs_reject_unknown_and_incoherent_variants() {
        assert_unknown_field_rejected::<GitHubAppConnectionCreateInput>(
            "appConnections.github.create",
            &json!({
                "name": "github-primary",
                "provider": {
                    "credentials": {
                        "method": "personalAccessToken",
                        "personalAccessToken": "canary",
                        "instance": { "kind": "cloud", "hostname": "unexpected" }
                    },
                    "route": { "kind": "direct" }
                }
            }),
        );
        let enterprise_cloud = parse_arguments::<GitHubAppConnectionCreateInput>(
            &mut request(
                "appConnections.github.create",
                &json!({
                    "name": "github-primary",
                    "provider": {
                        "credentials": {
                            "method": "personalAccessToken",
                            "personalAccessToken": "canary",
                            "instance": { "kind": "cloud", "host": "octocat.ghe.com" }
                        },
                        "route": { "kind": "direct" }
                    }
                }),
            ),
            "enterprise cloud input must match the declared schema",
        )
        .unwrap();
        enterprise_cloud.into_creation().unwrap();
        assert_unknown_field_rejected::<GitHubAppConnectionUpdateInput>(
            "appConnections.github.update",
            &json!({
                "connectionId": "bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb",
                "description": { "kind": "clear", "value": "unexpected" }
            }),
        );
        assert_unknown_field_rejected::<GitHubSecretSyncCreateInput>(
            "secretSyncs.github.create",
            &json!({
                "projectId": "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa",
                "name": "github-actions",
                "connectionId": "bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb",
                "environment": "prod",
                "secretPath": "/apps",
                "config": {
                    "destination": {
                        "scope": "repository",
                        "owner": "platform",
                        "repo": "api",
                        "visibility": "private"
                    },
                    "options": {}
                },
                "confirmInitialOverwrite": true
            }),
        );
        let duplicate_repositories = parse_arguments::<GitHubSecretSyncCreateInput>(
            &mut request(
                "secretSyncs.github.create",
                &json!({
                    "projectId": "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa",
                    "name": "github-actions",
                    "connectionId": "bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb",
                    "environment": "prod",
                    "secretPath": "/apps",
                    "config": {
                        "destination": {
                            "scope": "organization",
                            "org": "platform",
                            "visibility": "selected",
                            "selectedRepositoryIds": [10, 10]
                        },
                        "options": {}
                    },
                    "confirmInitialOverwrite": true
                }),
            ),
            "GitHub sync input must parse before semantic validation",
        )
        .unwrap();
        assert!(duplicate_repositories.into_parts().is_err());
    }

