    const CA_OPERATION_PROJECT_ID: &str = "22222222-2222-4222-8222-222222222222";
    const CA_OPERATION_ID: &str = "11111111-1111-4111-8111-111111111111";
    const CA_OPERATION_CERTIFICATE_ID: &str = "44444444-4444-4444-8444-444444444444";
    fn ca_operation_certificate() -> Value {
        json!({
            "certificate": ca_certificate_fixture(),
            "certificateChain": ca_certificate_fixture(),
            "serialNumber": "01ab",
            "certId": CA_OPERATION_CERTIFICATE_ID
        })
    }

    async fn mount_ca_operation_reads(server: &MockServer) {
        let authority = json!({
            "id": CA_OPERATION_ID,
            "projectId": CA_OPERATION_PROJECT_ID,
            "name": "root-ca",
            "type": "internal",
            "status": "active",
            "enableDirectIssuance": false,
            "configuration": {
                "type": "root",
                "commonName": "Root CA",
                "keyAlgorithm": "RSA_2048",
                "activeCaCertId": CA_OPERATION_CERTIFICATE_ID,
                "crlDistributionPointUrls": [],
                "disableManagedCrlDistributionPointUrl": false
            }
        });
        let mut pending_authority = authority.clone();
        pending_authority["status"] = json!("pending-certificate");
        pending_authority["configuration"]["activeCaCertId"] = Value::Null;
        let request_index = Arc::new(AtomicUsize::new(0));
        let responder_index = Arc::clone(&request_index);
        Mock::given(method("GET"))
            .and(path(format!(
                "/api/v1/cert-manager/ca/internal/{CA_OPERATION_ID}"
            )))
            .respond_with(move |_: &wiremock::Request| {
                let sequence = responder_index.fetch_add(1, Ordering::SeqCst);
                let response = if matches!(sequence, 4 | 7) {
                    pending_authority.clone()
                } else {
                    authority.clone()
                };
                ResponseTemplate::new(200).set_body_json(response)
            })
            .expect(9)
            .mount(server)
            .await;
        let mut historical = ca_operation_certificate();
        historical["version"] = json!(1);
        for (route, response) in [
            ("csr".to_owned(), json!({ "csr": ca_csr_fixture() })),
            ("ca-certificates".to_owned(), json!([historical])),
            ("certificate".to_owned(), ca_operation_certificate()),
            (
                format!("certificate/{CA_OPERATION_CERTIFICATE_ID}"),
                ca_operation_certificate(),
            ),
            (
                "crls".to_owned(),
                json!([{ "id": "55555555-5555-4555-8555-555555555555", "crl": ca_crl_fixture() }]),
            ),
        ] {
            Mock::given(method("GET"))
                .and(path(format!(
                    "/api/v1/cert-manager/ca/internal/{CA_OPERATION_ID}/{route}"
                )))
                .respond_with(ResponseTemplate::new(200).set_body_json(response))
                .expect(1)
                .mount(server)
                .await;
        }
    }

    async fn mount_ca_operation_mutations(server: &MockServer) {
        for (route, body, response) in [
            (
                "certificate",
                json!({
                    "notBefore": "2036-01-01T00:00:00Z",
                    "notAfter": "2037-01-01T00:00:00Z",
                    "maxPathLength": -1
                }),
                ca_operation_certificate(),
            ),
            (
                "renew",
                json!({ "type": "existing", "notAfter": "2038-01-01T00:00:00Z" }),
                ca_operation_certificate(),
            ),
            (
                "sign-intermediate",
                json!({
                    "csr": ca_csr_fixture(),
                    "notAfter": "2039-01-01T00:00:00Z",
                    "maxPathLength": -1
                }),
                json!({
                    "certificate": ca_certificate_fixture(),
                    "certificateChain": ca_certificate_fixture(),
                    "issuingCaCertificate": ca_certificate_fixture(),
                    "serialNumber": "02cd"
                }),
            ),
            (
                "import-certificate",
                json!({
                    "certificate": ca_certificate_fixture(),
                    "certificateChain": ca_certificate_fixture()
                }),
                json!({
                    "message": "Successfully imported certificate to CA",
                    "caId": CA_OPERATION_ID
                }),
            ),
        ] {
            Mock::given(method("POST"))
                .and(path(format!(
                    "/api/v1/cert-manager/ca/internal/{CA_OPERATION_ID}/{route}"
                )))
                .and(body_json(body))
                .respond_with(ResponseTemplate::new(200).set_body_json(response))
                .expect(1)
                .mount(server)
                .await;
        }
    }

    fn ca_operation_requests() -> [(&'static str, Value); 9] {
        let target = || json!({ "projectId": CA_OPERATION_PROJECT_ID, "caId": CA_OPERATION_ID });
        [
            ("certificateAuthorities.internal.csr.get", target()),
            (
                "certificateAuthorities.internal.certificates.list",
                target(),
            ),
            ("certificateAuthorities.internal.certificate.get", target()),
            (
                "certificateAuthorities.internal.certificateVersion.get",
                json!({ "target": target(), "certificateId": CA_OPERATION_CERTIFICATE_ID }),
            ),
            (
                "certificateAuthorities.internal.certificate.generate",
                json!({ "target": target(), "notBefore": "2036-01-01T00:00:00Z", "notAfter": "2037-01-01T00:00:00Z", "confirm": true }),
            ),
            (
                "certificateAuthorities.internal.certificate.renew",
                json!({ "target": target(), "notAfter": "2038-01-01T00:00:00Z", "confirm": true }),
            ),
            (
                "certificateAuthorities.internal.intermediate.sign",
                json!({ "target": target(), "csr": ca_csr_fixture(), "notAfter": "2039-01-01T00:00:00Z", "confirm": true }),
            ),
            (
                "certificateAuthorities.internal.certificate.import",
                json!({ "target": target(), "certificate": ca_certificate_fixture(), "certificateChain": ca_certificate_fixture(), "confirm": true }),
            ),
            ("certificateAuthorities.internal.crls.list", target()),
        ]
    }

    #[tokio::test]
    async fn internal_ca_certificate_handlers_dispatch_every_pinned_route() {
        let server = MockServer::start().await;
        mount_ca_operation_reads(&server).await;
        mount_ca_operation_mutations(&server).await;
        let client = client(&server).await;
        for (name, arguments) in ca_operation_requests() {
            let result = dispatch_tool(&client, None, request(name, &arguments))
                .await
                .unwrap();
            assert_ne!(result.is_error, Some(true), "{name}");
            assert!(result.structured_content.is_some(), "{name}");
        }
    }

    #[test]
    fn kms_bulk_input_cardinality_is_exact_at_the_mcp_boundary() {
        let project_id = "11111111-1111-4111-8111-111111111111";
        let import_keys = |count: usize| {
            (0..count)
                .map(|index| {
                    json!({
                        "name": format!("key-{index}"),
                        "keyUsage": "encrypt-decrypt",
                        "algorithm": "aes-256-gcm",
                        "keyMaterial": "AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA="
                    })
                })
                .collect::<Vec<_>>()
        };
        for (count, valid) in [(0, false), (1, true), (100, true), (101, false)] {
            let input = parse_arguments::<KmsBulkImportInput>(
                &mut request(
                    "kms.keys.bulkImport",
                    &json!({
                        "projectId": project_id,
                        "keys": import_keys(count),
                        "confirm": true
                    }),
                ),
                "KMS bulk import input must parse before semantic validation",
            )
            .unwrap();
            assert_eq!(input.into_parts().is_ok(), valid, "import count {count}");
        }

        let key_ids = |count: usize| {
            (0..count)
                .map(|index| format!("00000000-0000-4000-8000-{index:012}"))
                .collect::<Vec<_>>()
        };
        for (count, valid) in [(0, false), (1, true), (100, true), (101, false)] {
            let input = parse_arguments::<KmsBulkPrivateKeyRevealInput>(
                &mut request(
                    "kms.keys.privateKeys.bulkReveal",
                    &json!({
                        "projectId": project_id,
                        "keyIds": key_ids(count),
                        "confirmReveal": true
                    }),
                ),
                "KMS bulk private-key input must parse before semantic validation",
            )
            .unwrap();
            assert_eq!(input.into_parts().is_ok(), valid, "reveal count {count}");
        }
    }

