    #[tokio::test]
    async fn kms_handlers_dispatch_audited_metadata_and_explicit_plaintext_reveal() {
        let server = MockServer::start().await;
        let project_id = "11111111-1111-4111-8111-111111111111";
        let key_id = "22222222-2222-4222-8222-222222222222";
        let key = json!({
            "id": key_id,
            "name": "application-key",
            "description": "application key",
            "isDisabled": false,
            "orgId": "44444444-4444-4444-8444-444444444444",
            "projectId": project_id,
            "keyUsage": "encrypt-decrypt",
            "encryptionAlgorithm": "aes-256-gcm",
            "version": 1,
            "createdAt": "2026-07-20T01:02:03.000Z",
            "updatedAt": "2026-07-20T01:02:03.000Z"
        });
        Mock::given(method("GET"))
            .and(path("/api/v1/kms/keys"))
            .and(query_param("projectId", project_id))
            .and(query_param("offset", "0"))
            .and(query_param("limit", "1"))
            .and(query_param("orderBy", "name"))
            .and(query_param("orderDirection", "asc"))
            .respond_with(ResponseTemplate::new(200).set_body_json(json!({
                "keys": [key.clone()],
                "totalCount": 1
            })))
            .expect(1)
            .mount(&server)
            .await;
        Mock::given(method("GET"))
            .and(path(format!("/api/v1/kms/keys/{key_id}")))
            .respond_with(ResponseTemplate::new(200).set_body_json(json!({ "key": key })))
            .expect(1)
            .mount(&server)
            .await;
        Mock::given(method("POST"))
            .and(path(format!("/api/v1/kms/keys/{key_id}/decrypt")))
            .and(body_json(json!({ "ciphertext": "Y2lwaGVydGV4dA==" })))
            .respond_with(ResponseTemplate::new(200).set_body_json(json!({
                "plaintext": "cGxhaW50ZXh0LWNhbmFyeQ=="
            })))
            .expect(1)
            .mount(&server)
            .await;

        let client = client(&server).await;
        let listed = dispatch_tool(
            &client,
            None,
            request(
                "kms.keys.list",
                &json!({ "projectId": project_id, "limit": 1 }),
            ),
        )
        .await
        .unwrap()
        .structured_content
        .unwrap();
        assert_eq!(listed["items"][0]["id"], key_id);
        assert!(
            serde_json::to_string(&listed)
                .unwrap()
                .contains("application-key")
        );
        assert!(
            !serde_json::to_string(&listed)
                .unwrap()
                .contains("plaintext")
        );

        let decrypted = dispatch_tool(
            &client,
            None,
            request(
                "kms.decrypt",
                &json!({
                    "target": { "projectId": project_id, "keyId": key_id },
                    "ciphertext": "Y2lwaGVydGV4dA==",
                    "confirmReveal": true
                }),
            ),
        )
        .await
        .unwrap()
        .structured_content
        .unwrap();
        assert_eq!(decrypted["keyId"], key_id);
        assert_eq!(decrypted["plaintext"], "cGxhaW50ZXh0LWNhbmFyeQ==");
    }

    #[test]
    fn sql_rotation_inputs_reject_unknown_fields_and_unconfirmed_reveal() {
        let target = json!({
            "provider": "postgres-credentials",
            "projectId": "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa",
            "rotationId": "22222222-2222-4222-8222-222222222222",
            "recursive": true
        });
        assert_unknown_field_rejected::<SqlSecretRotationTargetInput>(
            "secretRotations.sql.get",
            &target,
        );
        assert_unknown_field_rejected::<SqlSecretRotationCreateInput>(
            "secretRotations.sql.create",
            &json!({
                "provider": "postgres-credentials",
                "projectId": "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa",
                "name": "database-password",
                "connectionId": "bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb",
                "environment": "prod",
                "secretPath": "/apps",
                "rotationIntervalDays": 30,
                "rotateAtUtc": { "hours": 3, "minutes": 15 },
                "config": {
                    "parameters": {
                        "username1": "app_user_a",
                        "username2": "app_user_b",
                        "rootPassword": "must-not-be-accepted"
                    },
                    "secretsMapping": { "username": "DB_USER", "password": "DB_PASSWORD" }
                },
                "confirmCreateCredentialsAndSecrets": true
            }),
        );
        let reveal = parse_arguments::<SqlGeneratedCredentialsGetInput>(
            &mut request(
                "secretRotations.sql.generatedCredentials.get",
                &json!({
                    "provider": "postgres-credentials",
                    "projectId": "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa",
                    "rotationId": "22222222-2222-4222-8222-222222222222",
                    "confirmReveal": false
                }),
            ),
            "SQL reveal input must parse before semantic confirmation",
        )
        .unwrap();
        assert!(!reveal.confirm_reveal);
    }

    #[test]
    fn dynamic_secret_administration_inputs_reject_unknown_fields_and_invalid_boundaries() {
        assert_unknown_field_rejected::<DynamicSecretsListInput>(
            "dynamicSecrets.list",
            &json!({
                "scope": {
                    "projectSlug": "platform",
                    "environmentSlug": "prod",
                    "path": "/database",
                    "recursive": true
                }
            }),
        );
        assert_unknown_field_rejected::<DynamicSecretLeasesListInput>(
            "dynamicSecretLeases.list",
            &json!({
                "scope": {
                    "projectSlug": "platform",
                    "environmentSlug": "prod",
                    "path": "/database"
                },
                "dynamicSecretName": "database-user",
                "limt": 10
            }),
        );
        assert_unknown_field_rejected::<DynamicSecretUpdateInput>(
            "dynamicSecrets.update",
            &json!({
                "target": {
                    "scope": {
                        "projectSlug": "platform",
                        "environmentSlug": "prod",
                        "path": "/database"
                    },
                    "dynamicSecretName": "database-user"
                },
                "change": {
                    "kind": "rename",
                    "newName": "database-writer",
                    "metadata": []
                }
            }),
        );
        assert_unknown_field_rejected::<DynamicSecretDeleteInput>(
            "dynamicSecrets.delete",
            &json!({
                "target": {
                    "scope": {
                        "projectSlug": "platform",
                        "environmentSlug": "prod",
                        "path": "/database"
                    },
                    "dynamicSecretName": "database-user",
                    "recursive": true
                },
                "confirm": true
            }),
        );

        let too_short = parse_arguments::<DynamicSecretLeaseRenewInput>(
            &mut request(
                "dynamicSecretLeases.renew",
                &json!({
                    "scope": {
                        "projectSlug": "platform",
                        "environmentSlug": "prod",
                        "path": "/database"
                    },
                    "leaseId": "4d40b103-d45a-44ca-a95f-57d7361a4d2a",
                    "ttlSeconds": 59
                }),
            ),
            "dynamic-secret renew arguments must parse before semantic validation",
        )
        .unwrap();
        assert!(too_short.into_parts().is_err());

        let incoherent_lifetime = parse_arguments::<DynamicSecretUpdateInput>(
            &mut request(
                "dynamicSecrets.update",
                &json!({
                    "target": {
                        "scope": {
                            "projectSlug": "platform",
                            "environmentSlug": "prod",
                            "path": "/database"
                        },
                        "dynamicSecretName": "database-user"
                    },
                    "change": {
                        "kind": "lifetime",
                        "defaultTtlSeconds": 7200,
                        "maxTtlSeconds": 3600
                    }
                }),
            ),
            "dynamic-secret update arguments must parse before semantic validation",
        )
        .unwrap();
        assert!(incoherent_lifetime.into_parts().is_err());
    }

    #[test]
    fn sql_dynamic_secret_inputs_reject_unknown_fields_and_invalid_templates() {
        let mut default_tls = sql_provider_input("root-canary", &json!({ "kind": "direct" }));
        default_tls
            .as_object_mut()
            .unwrap()
            .remove("sslRejectUnauthorized");
        let default_tls: SqlDynamicSecretProviderInputsInput =
            serde_json::from_value(default_tls).unwrap();
        assert!(default_tls.ssl_reject_unauthorized);

        let mut oracle = sql_provider_input("root-canary", &json!({ "kind": "direct" }));
        oracle["client"] = json!("oracle");
        oracle["passwordRequirements"] = json!({
            "length": 31,
            "lowercase": 1,
            "uppercase": 1,
            "digits": 1,
            "symbols": 0
        });
        let oracle = parse_arguments::<DynamicSecretCreateInput>(
            &mut request(
                "dynamicSecrets.create",
                &json!({
                    "scope": dynamic_secret_scope_input(),
                    "name": "database-user",
                    "defaultTtlSeconds": 3600,
                    "provider": { "type": "sqlDatabase", "inputs": oracle }
                }),
            ),
            "Oracle policy must parse before provider-specific validation",
        )
        .unwrap();
        assert!(oracle.into_parts().is_err());

        assert_unknown_field_rejected::<DynamicSecretCreateInput>(
            "dynamicSecrets.create",
            &json!({
                "scope": dynamic_secret_scope_input(),
                "name": "database-user",
                "defaultTtlSeconds": 3600,
                "maxTtlSeconds": 86400,
                "provider": {
                    "type": "sqlDatabase",
                    "inputs": sql_provider_input("root-canary", &json!({ "kind": "direct" })),
                    "metadata": { "unbounded": true }
                }
            }),
        );
        let invalid_template = parse_arguments::<DynamicSecretCreateInput>(
            &mut request(
                "dynamicSecrets.create",
                &json!({
                    "scope": dynamic_secret_scope_input(),
                    "name": "database-user",
                    "defaultTtlSeconds": 3600,
                    "provider": {
                        "type": "sqlDatabase",
                        "inputs": sql_provider_input("root-canary", &json!({ "kind": "direct" }))
                    }
                }),
            ),
            "dynamic-secret create arguments must parse before semantic validation",
        )
        .unwrap();
        let DynamicSecretProviderInput::SqlDatabase { inputs } = invalid_template.provider;
        let invalid_inputs = SqlDynamicSecretProviderInputsInput {
            creation_statement: "CREATE USER {{unsupported}}".to_owned(),
            ..inputs
        };
        assert!(invalid_inputs.into_inputs().is_err());
    }

