    #[tokio::test]
    async fn app_automation_inventory_handlers_dispatch_value_free_observable_reads() {
        let server = MockServer::start().await;
        let client = client(&server).await;
        let project_id = "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa";
        let connection_id = "bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb";
        let folder_id = "cccccccc-cccc-4ccc-8ccc-cccccccccccc";
        let environment_id = "dddddddd-dddd-4ddd-8ddd-dddddddddddd";
        mount_app_automation_project_fixture(&server, project_id, environment_id).await;
        mount_app_connection_inventory_fixture(&server, project_id, connection_id).await;
        mount_secret_sync_inventory_fixture(
            &server,
            project_id,
            connection_id,
            folder_id,
            environment_id,
        )
        .await;
        mount_secret_rotation_inventory_fixture(
            &server,
            project_id,
            connection_id,
            folder_id,
            environment_id,
        )
        .await;

        for (name, expected_id) in [
            ("appConnections.list", connection_id),
            ("secretSyncs.list", "11111111-1111-4111-8111-111111111111"),
            (
                "secretRotations.list",
                "22222222-2222-4222-8222-222222222222",
            ),
        ] {
            let result = dispatch_tool(
                &client,
                None,
                request(name, &json!({ "projectId": project_id, "limit": 10 })),
            )
            .await
            .unwrap()
            .structured_content
            .unwrap();
            assert_eq!(result["items"][0]["id"], expected_id);
            assert!(!result.to_string().contains("handler-sensitive-canary"));
        }
    }

