    fn sql_provider_wire_input(password: &str) -> Value {
        json!({
            "client": "postgres",
            "host": "db.internal",
            "port": 5432,
            "database": "app",
            "username": "root",
            "password": password,
            "passwordRequirements": {
                "length": 48,
                "required": {
                    "lowercase": 1,
                    "uppercase": 1,
                    "digits": 1,
                    "symbols": 0
                },
                "allowedSymbols": "-_.~!*"
            },
            "creationStatement": "CREATE USER {{username}} WITH PASSWORD '{{password}}'",
            "revocationStatement": "DROP USER {{username}}",
            "renewStatement": "ALTER USER {{username}} VALID UNTIL '{{expiration}}'",
            "ca": "",
            "sslEnabled": false,
            "sslRejectUnauthorized": true,
            "gatewayId": null,
            "gatewayPoolId": null
        })
    }

