    #[tokio::test]
    async fn dynamic_secret_list_and_renew_handlers_keep_results_value_free() {
        let server = MockServer::start().await;
        let client = client(&server).await;
        let config_id = "0b30c3c2-6a13-485f-9775-9768d8d2708a";
        let folder_id = "573a2b87-7f44-4fb4-81ca-851679a7419f";
        let lease_id = "4d40b103-d45a-44ca-a95f-57d7361a4d2a";
        let configuration = dynamic_secret_handler_configuration(config_id, folder_id);
        let lease = dynamic_secret_handler_lease(config_id, lease_id);
        Mock::given(method("GET"))
            .and(path("/api/v1/dynamic-secrets"))
            .and(query_param("projectSlug", "platform"))
            .and(query_param("environmentSlug", "prod"))
            .and(query_param("path", "/database"))
            .respond_with(ResponseTemplate::new(200).set_body_json(json!({
                "dynamicSecrets": [configuration]
            })))
            .expect(1)
            .mount(&server)
            .await;
        Mock::given(method("POST"))
            .and(path(format!(
                "/api/v1/dynamic-secrets/leases/{lease_id}/renew"
            )))
            .and(body_json(json!({
                "projectSlug": "platform",
                "environmentSlug": "prod",
                "path": "/database",
                "ttl": "7200s"
            })))
            .respond_with(ResponseTemplate::new(200).set_body_json(json!({ "lease": lease })))
            .expect(1)
            .mount(&server)
            .await;

        let scope = json!({
            "projectSlug": "platform",
            "environmentSlug": "prod",
            "path": "/database"
        });
        let listed = dispatch_tool(
            &client,
            None,
            request(
                "dynamicSecrets.list",
                &json!({ "scope": scope.clone(), "limit": 10 }),
            ),
        )
        .await
        .unwrap()
        .structured_content
        .unwrap();
        assert_eq!(listed["items"][0]["name"], "database-user");
        let listed_wire = serde_json::to_string(&listed).unwrap();
        assert!(!listed_wire.contains("handler-sensitive-canary"));
        assert!(!listed_wire.contains("inputs"));
        assert!(!listed_wire.contains("metadata"));

        let renewed = dispatch_tool(
            &client,
            None,
            request(
                "dynamicSecretLeases.renew",
                &json!({
                    "scope": scope,
                    "leaseId": lease_id,
                    "ttlSeconds": 7200
                }),
            ),
        )
        .await
        .unwrap()
        .structured_content
        .unwrap();
        assert_eq!(renewed["id"], lease_id);
        assert!(
            !serde_json::to_string(&renewed)
                .unwrap()
                .contains("handler-sensitive-canary")
        );
    }

