    #[tokio::test]
    async fn sql_dynamic_secret_handlers_keep_inputs_secret_and_reveal_lease_password_once() {
        let server = MockServer::start().await;
        let client = client(&server).await;
        let config_id = "0b30c3c2-6a13-485f-9775-9768d8d2708a";
        let folder_id = "573a2b87-7f44-4fb4-81ca-851679a7419f";
        let lease_id = "4d40b103-d45a-44ca-a95f-57d7361a4d2a";
        mount_sql_dynamic_secret_handler_fixtures(&server, config_id, folder_id, lease_id).await;
        let provider = |password| {
            json!({
                "type": "sqlDatabase",
                "inputs": sql_provider_input(password, &json!({ "kind": "direct" }))
            })
        };
        let target = json!({
            "scope": dynamic_secret_scope_input(),
            "dynamicSecretName": "database-user"
        });

        let created = dispatch_tool(
            &client,
            None,
            request(
                "dynamicSecrets.create",
                &json!({
                    "scope": dynamic_secret_scope_input(),
                    "name": "database-user",
                    "defaultTtlSeconds": 3600,
                    "maxTtlSeconds": 86400,
                    "provider": provider("create-root-canary")
                }),
            ),
        )
        .await
        .unwrap()
        .structured_content
        .unwrap();
        let lease = dispatch_tool(
            &client,
            None,
            request(
                "dynamicSecretLeases.create",
                &json!({
                    "target": target,
                    "provider": { "type": "sqlDatabase" },
                    "ttlSeconds": 7200
                }),
            ),
        )
        .await
        .unwrap()
        .structured_content
        .unwrap();

        assert_eq!(created["id"], config_id);
        assert_eq!(lease["provider"], "sqlDatabase");
        assert_eq!(lease["lease"]["id"], lease_id);
        assert_eq!(lease["username"], "svc-lease-user");
        assert_eq!(lease["password"], "lease-password-canary");
        let value_free = created.to_string();
        assert!(!value_free.contains("create-root-canary"));
        assert!(!value_free.contains("handler-sensitive-canary"));
    }

