    #[test]
    fn folder_inputs_preserve_root_default_complete_description_and_batch_bounds() {
        let creation = parse_arguments::<FolderCreateInput>(
            &mut request(
                "folders.create",
                &json!({
                    "parent": { "projectId": "project-1", "environment": "prod" },
                    "name": "api"
                }),
            ),
            "valid folder creation",
        )
        .unwrap()
        .into_creation()
        .unwrap();
        assert_eq!(creation.parent.path.as_str(), "/");

        let update = parse_arguments::<FolderUpdateInput>(
            &mut request(
                "folders.update",
                &json!({
                    "target": folder_target(),
                    "name": "api",
                    "description": "API credentials"
                }),
            ),
            "valid folder update",
        )
        .unwrap()
        .into_update()
        .unwrap();
        assert_eq!(
            update
                .description
                .as_ref()
                .map(infisical_api::FolderDescription::as_str),
            Some("API credentials")
        );

        for (count, expected_ok) in [(0, false), (50, true), (51, false)] {
            let folders = (0..count)
                .map(|index| {
                    json!({
                        "folderId": format!("folder-{index}"),
                        "environment": "prod",
                        "path": "/payments",
                        "name": format!("folder_{index}"),
                        "description": null
                    })
                })
                .collect::<Vec<_>>();
            let input = parse_arguments::<FolderBatchUpdateInput>(
                &mut request(
                    "folders.batch.update",
                    &json!({ "projectId": "project-1", "folders": folders }),
                ),
                "valid folder batch update",
            )
            .unwrap();
            assert_eq!(
                input.into_parts().is_ok(),
                expected_ok,
                "batch size {count}"
            );
        }
    }

