    #[tokio::test]
    async fn secret_import_handlers_dispatch_all_supported_mapping_workflows() {
        let server = MockServer::start().await;
        let client = client(&server).await;
        mount_secret_import_fixtures(&server).await;

        let listed = dispatch_tool(
            &client,
            None,
            request(
                "secretImports.list",
                &json!({ "target": batch_scope(), "limit": 10 }),
            ),
        )
        .await
        .unwrap()
        .structured_content
        .unwrap();
        let fetched = dispatch_tool(
            &client,
            None,
            request(
                "secretImports.get",
                &json!({ "secretImportId": "import-1" }),
            ),
        )
        .await
        .unwrap()
        .structured_content
        .unwrap();
        let created = dispatch_tool(
            &client,
            None,
            request(
                "secretImports.create",
                &json!({
                    "target": batch_scope(),
                    "source": { "environment": "staging", "path": "/shared" }
                }),
            ),
        )
        .await
        .unwrap()
        .structured_content
        .unwrap();
        let updated = dispatch_tool(
            &client,
            None,
            request(
                "secretImports.update",
                &json!({
                    "target": batch_scope(),
                    "secretImportId": "import-1",
                    "change": { "kind": "position", "position": 2 }
                }),
            ),
        )
        .await
        .unwrap()
        .structured_content
        .unwrap();
        let deleted = dispatch_tool(
            &client,
            None,
            request(
                "secretImports.delete",
                &json!({
                    "target": batch_scope(),
                    "secretImportId": "import-1",
                    "confirm": true
                }),
            ),
        )
        .await
        .unwrap()
        .structured_content
        .unwrap();

        assert_eq!(listed["items"][0]["id"], "import-1");
        assert_eq!(fetched["target"]["environment"], "prod");
        assert_eq!(created["source"]["environment"]["slug"], "staging");
        assert_eq!(updated["position"], 2);
        assert_eq!(deleted["id"], "import-1");
        for output in [listed, fetched, created, updated, deleted] {
            assert!(
                !serde_json::to_string(&output)
                    .unwrap()
                    .contains("secretValue")
            );
        }
    }

