    async fn assert_identity_handlers(client: &InfisicalClient) {
        let listed = dispatch_tool(
            client,
            None,
            request(
                "identities.list",
                &json!({ "organizationId": "org-1", "limit": 1 }),
            ),
        )
        .await
        .unwrap()
        .structured_content
        .unwrap();
        let fetched = dispatch_tool(
            client,
            None,
            request("identities.get", &json!({ "identityId": "identity-1" })),
        )
        .await
        .unwrap()
        .structured_content
        .unwrap();
        let created = dispatch_tool(
            client,
            None,
            request(
                "identities.create",
                &json!({ "name": "agent-one", "organizationId": "org-1" }),
            ),
        )
        .await
        .unwrap()
        .structured_content
        .unwrap();
        for change in [
            json!({ "kind": "name", "name": "agent-renamed" }),
            json!({ "kind": "role", "role": "member" }),
            json!({ "kind": "deleteProtection", "enabled": false }),
        ] {
            dispatch_tool(
                client,
                None,
                request(
                    "identities.update",
                    &json!({ "identityId": "identity-1", "change": change }),
                ),
            )
            .await
            .unwrap();
        }
        let deleted = dispatch_tool(
            client,
            None,
            request(
                "identities.delete",
                &json!({ "identityId": "identity-1", "confirm": true }),
            ),
        )
        .await
        .unwrap()
        .structured_content
        .unwrap();

        assert_eq!(listed["items"][0]["organizationRole"], "no-access");
        assert_eq!(fetched["organizationMembershipId"], "membership-1");
        assert_eq!(created["name"], "agent-one");
        assert_eq!(deleted["id"], "identity-1");
    }

