    #[tokio::test]
    async fn role_handlers_dispatch_supported_reads_without_synthetic_state() {
        let server = MockServer::start().await;
        let client = client(&server).await;
        mount_role_handler_fixtures(&server).await;

        let project_roles = dispatch_tool(
            &client,
            None,
            request("projectRoles.list", &json!({ "projectId": "project-1" })),
        )
        .await
        .unwrap()
        .structured_content
        .unwrap();
        let project_role = dispatch_tool(
            &client,
            None,
            request(
                "projectRoles.get",
                &json!({ "projectId": "project-1", "roleSlug": "deployer" }),
            ),
        )
        .await
        .unwrap()
        .structured_content
        .unwrap();
        let organization_roles =
            dispatch_tool(&client, None, request("organizationRoles.list", &json!({})))
                .await
                .unwrap()
                .structured_content
                .unwrap();
        let organization_role = dispatch_tool(
            &client,
            None,
            request("organizationRoles.get", &json!({ "roleSlug": "auditor" })),
        )
        .await
        .unwrap()
        .structured_content
        .unwrap();

        assert_eq!(project_roles["items"][0]["builtIn"], true);
        assert_eq!(project_role["permissions"][0]["action"][0], "read");
        assert_eq!(organization_roles["items"][0]["scope"], "organization");
        assert_eq!(organization_role["slug"], "auditor");
        for output in [
            project_roles["items"][0].clone(),
            project_role,
            organization_roles["items"][0].clone(),
            organization_role,
        ] {
            assert!(output.get("id").is_none());
            assert!(output.get("createdAt").is_none());
            assert!(output.get("updatedAt").is_none());
        }
    }

