    #[tokio::test]
    async fn additional_privilege_handlers_dispatch_the_complete_v2_lifecycle() {
        let server = MockServer::start().await;
        let client = client(&server).await;
        mount_additional_privilege_handler_fixtures(&server).await;

        let listed = call_additional_privilege(
            &client,
            "identityProjectAdditionalPrivileges.list",
            json!({ "projectId": "project-1", "identityId": "identity-1" }),
        )
        .await;
        let fetched = call_additional_privilege(
            &client,
            "identityProjectAdditionalPrivileges.get",
            json!({
                "projectId": "project-1",
                "identityId": "identity-1",
                "privilegeId": "privilege-1"
            }),
        )
        .await;
        let by_slug = call_additional_privilege(
            &client,
            "identityProjectAdditionalPrivileges.getBySlug",
            json!({
                "projectId": "project-1",
                "projectSlug": "payments",
                "identityId": "identity-1",
                "privilegeSlug": "auditor"
            }),
        )
        .await;
        let created = call_additional_privilege(
            &client,
            "identityProjectAdditionalPrivileges.create",
            json!({
                "projectId": "project-1",
                "identityId": "identity-1",
                "slug": "temporary-auditor",
                "permissions": [{
                    "subject": "secrets",
                    "action": ["read"],
                    "inverted": true
                }],
                "confirmDenyPermissions": true,
                "lifetime": {
                    "kind": "temporary",
                    "durationSeconds": 3600,
                    "startTime": "2026-07-20T12:00:00Z"
                }
            }),
        )
        .await;
        let updated = call_additional_privilege(
            &client,
            "identityProjectAdditionalPrivileges.update",
            json!({
                "projectId": "project-1",
                "identityId": "identity-1",
                "privilegeId": "privilege-1",
                "slug": "operator",
                "permissions": [],
                "confirmReplacePermissions": true,
                "lifetime": { "kind": "permanent" }
            }),
        )
        .await;
        let deleted = call_additional_privilege(
            &client,
            "identityProjectAdditionalPrivileges.delete",
            json!({
                "projectId": "project-1",
                "identityId": "identity-1",
                "privilegeId": "privilege-1",
                "confirmDelete": true
            }),
        )
        .await;

        assert_eq!(listed["items"][0]["slug"], "auditor");
        assert_eq!(fetched["permissions"][0]["subject"], "secrets");
        assert_eq!(by_slug["id"], "privilege-1");
        assert_eq!(created["slug"], "temporary-auditor");
        assert_eq!(updated["slug"], "operator");
        assert_eq!(updated["permissions"], json!([]));
        assert_eq!(deleted["id"], "privilege-1");
    }

    #[tokio::test]
    async fn additional_privilege_deny_replacement_and_deletion_require_confirmation_before_auth() {
        let server = MockServer::start().await;
        let client = InfisicalClient::new(ClientSettings::new(
            server.uri().parse().unwrap(),
            "handler-client".into(),
            SecretValue::new("handler-client-secret"),
        ))
        .unwrap();
        let creation = dispatch_tool(
            &client,
            None,
            request(
                "identityProjectAdditionalPrivileges.create",
                &json!({
                    "projectId": "project-1",
                    "identityId": "identity-1",
                    "permissions": [{
                        "subject": "secrets",
                        "action": ["read"],
                        "inverted": true
                    }],
                    "lifetime": { "kind": "permanent" }
                }),
            ),
        )
        .await
        .unwrap_err();
        assert_eq!(creation.code, rmcp::model::ErrorCode::INVALID_PARAMS);
        let update = dispatch_tool(
            &client,
            None,
            request(
                "identityProjectAdditionalPrivileges.update",
                &json!({
                    "projectId": "project-1",
                    "identityId": "identity-1",
                    "privilegeId": "privilege-1",
                    "slug": "operator",
                    "permissions": [],
                    "lifetime": { "kind": "permanent" }
                }),
            ),
        )
        .await
        .unwrap_err();
        assert_eq!(update.code, rmcp::model::ErrorCode::INVALID_PARAMS);
        let deletion = dispatch_tool(
            &client,
            None,
            request(
                "identityProjectAdditionalPrivileges.delete",
                &json!({
                    "projectId": "project-1",
                    "identityId": "identity-1",
                    "privilegeId": "privilege-1",
                    "confirmDelete": false
                }),
            ),
        )
        .await
        .unwrap_err();
        assert_eq!(deletion.code, rmcp::model::ErrorCode::INVALID_PARAMS);
        assert!(server.received_requests().await.unwrap().is_empty());
    }

