    async fn assert_universal_auth_config_handlers(client: &InfisicalClient) {
        let config = dispatch_tool(
            client,
            None,
            request(
                "identityUniversalAuth.get",
                &json!({ "identityId": "identity-1" }),
            ),
        )
        .await
        .unwrap()
        .structured_content
        .unwrap();
        dispatch_tool(
            client,
            None,
            request(
                "identityUniversalAuth.attach",
                &json!({ "identityId": "identity-1" }),
            ),
        )
        .await
        .unwrap();
        for change in [
            json!({
                "kind": "tokenLifetime",
                "accessTokenTTL": 1800,
                "accessTokenMaxTTL": 7200,
                "accessTokenPeriod": 0
            }),
            json!({ "kind": "accessTokenUseLimit", "limit": 20 }),
            json!({
                "kind": "lockoutPolicy",
                "enabled": true,
                "threshold": 5,
                "durationSeconds": 600,
                "counterResetSeconds": 60
            }),
        ] {
            dispatch_tool(
                client,
                None,
                request(
                    "identityUniversalAuth.update",
                    &json!({ "identityId": "identity-1", "change": change }),
                ),
            )
            .await
            .unwrap();
        }
        let cleared = dispatch_tool(
            client,
            None,
            request(
                "identityUniversalAuth.lockouts.clear",
                &json!({ "identityId": "identity-1", "confirm": true }),
            ),
        )
        .await
        .unwrap()
        .structured_content
        .unwrap();
        dispatch_tool(
            client,
            None,
            request(
                "identityUniversalAuth.remove",
                &json!({ "identityId": "identity-1", "confirm": true }),
            ),
        )
        .await
        .unwrap();

        assert_eq!(config["clientId"], "public-client-id");
        assert_eq!(cleared["deleted"], 2);
    }

