    async fn mount_token_auth_handler_fixtures(server: &MockServer) {
        let config_route = "/api/v1/auth/token-auth/identities/identity-1";
        for (method_name, body) in [
            (
                "POST",
                json!({
                    "accessTokenTTL": 3600,
                    "accessTokenMaxTTL": 86400,
                    "accessTokenNumUsesLimit": 10
                }),
            ),
            (
                "PATCH",
                json!({ "accessTokenTTL": 1800, "accessTokenMaxTTL": 7200 }),
            ),
            ("PATCH", json!({ "accessTokenNumUsesLimit": 20 })),
            ("DELETE", json!({})),
        ] {
            Mock::given(method(method_name))
                .and(path(config_route))
                .and(body_json(body))
                .respond_with(ResponseTemplate::new(200).set_body_json(json!({
                    "identityTokenAuth": token_auth_fixture()
                })))
                .expect(1)
                .mount(server)
                .await;
        }
        Mock::given(method("GET"))
            .and(path(config_route))
            .respond_with(ResponseTemplate::new(200).set_body_json(json!({
                "identityTokenAuth": token_auth_fixture()
            })))
            .expect(1)
            .mount(server)
            .await;

        let collection = format!("{config_route}/tokens");
        Mock::given(method("GET"))
            .and(path(collection.as_str()))
            .and(query_param("offset", "0"))
            .and(query_param("limit", "2"))
            .respond_with(ResponseTemplate::new(200).set_body_json(json!({
                "tokens": [
                    token_auth_token_fixture("token-1", "first", false),
                    token_auth_token_fixture("token-2", "second", false)
                ]
            })))
            .expect(1)
            .mount(server)
            .await;
        Mock::given(method("GET"))
            .and(path("/api/v1/auth/token-auth/tokens/token-2"))
            .respond_with(ResponseTemplate::new(200).set_body_json(json!({
                "token": token_auth_token_fixture("token-2", "second", false)
            })))
            .expect(1)
            .mount(server)
            .await;
        Mock::given(method("POST"))
            .and(path(collection.as_str()))
            .and(body_json(
                json!({ "name": "gateway", "organizationSlug": "child-org" }),
            ))
            .respond_with(ResponseTemplate::new(200).set_body_json(json!({
                "accessToken": "generated-token-canary",
                "expiresIn": 3600,
                "accessTokenMaxTTL": 86400,
                "tokenType": "Bearer",
                "tokenData": token_auth_token_fixture("token-3", "gateway", false)
            })))
            .expect(1)
            .mount(server)
            .await;
        Mock::given(method("PATCH"))
            .and(path("/api/v1/auth/token-auth/tokens/token-2"))
            .and(body_json(json!({ "name": "renamed" })))
            .respond_with(ResponseTemplate::new(200).set_body_json(json!({
                "token": token_auth_token_fixture("token-2", "renamed", false)
            })))
            .expect(1)
            .mount(server)
            .await;
        Mock::given(method("POST"))
            .and(path("/api/v1/auth/token-auth/tokens/token-2/revoke"))
            .and(body_json(json!({})))
            .respond_with(ResponseTemplate::new(200).set_body_json(json!({
                "message": "Successfully revoked access token"
            })))
            .expect(1)
            .mount(server)
            .await;
    }

