    async fn assert_token_auth_token_handlers(client: &InfisicalClient) {
        let listed = dispatch_tool(
            client,
            None,
            request(
                "identityTokenAuth.tokens.list",
                &json!({
                    "identityId": "identity-1",
                    "offset": 0,
                    "limit": 2
                }),
            ),
        )
        .await
        .unwrap()
        .structured_content
        .unwrap();
        let fetched = dispatch_tool(
            client,
            None,
            request(
                "identityTokenAuth.tokens.get",
                &json!({ "tokenId": "token-2" }),
            ),
        )
        .await
        .unwrap()
        .structured_content
        .unwrap();
        let created = dispatch_tool(
            client,
            None,
            request(
                "identityTokenAuth.tokens.create",
                &json!({
                    "identityId": "identity-1",
                    "name": "gateway",
                    "organizationSlug": "child-org"
                }),
            ),
        )
        .await
        .unwrap()
        .structured_content
        .unwrap();
        let updated = dispatch_tool(
            client,
            None,
            request(
                "identityTokenAuth.tokens.update",
                &json!({
                    "tokenId": "token-2",
                    "name": "renamed"
                }),
            ),
        )
        .await
        .unwrap()
        .structured_content
        .unwrap();
        let revoked = dispatch_tool(
            client,
            None,
            request(
                "identityTokenAuth.tokens.revoke",
                &json!({
                    "tokenId": "token-2",
                    "confirm": true
                }),
            ),
        )
        .await
        .unwrap()
        .structured_content
        .unwrap();
        assert_eq!(listed["items"][1]["id"], "token-2");
        assert_eq!(fetched["name"], "second");
        assert_eq!(created["accessToken"], "generated-token-canary");
        assert_eq!(created["metadata"]["id"], "token-3");
        assert_eq!(updated["name"], "renamed");
        assert_eq!(revoked["message"], "Successfully revoked access token");
    }

