    #[tokio::test]
    #[allow(clippy::too_many_lines)]
    async fn code_signer_handlers_dispatch_reads_and_non_replayed_signing() {
        let server = MockServer::start().await;
        let client = client(&server).await;
        let project_id = "11111111-1111-4111-8111-111111111111";
        let signer_id = "22222222-2222-4222-8222-222222222222";
        let certificate_id = "33333333-3333-4333-8333-333333333333";
        let signer = code_signer_fixture(project_id, signer_id, certificate_id);
        Mock::given(method("GET"))
            .and(path("/api/v1/cert-manager/signers"))
            .and(query_param("projectId", project_id))
            .and(query_param("offset", "0"))
            .and(query_param("limit", "50"))
            .respond_with(ResponseTemplate::new(200).set_body_json(json!({
                "signers": [signer.clone()],
                "totalCount": 1
            })))
            .expect(1)
            .mount(&server)
            .await;
        Mock::given(method("GET"))
            .and(path(format!("/api/v1/cert-manager/signers/{signer_id}")))
            .respond_with(ResponseTemplate::new(200).set_body_json(signer))
            .expect(4)
            .mount(&server)
            .await;
        Mock::given(method("GET"))
            .and(path(format!(
                "/api/v1/cert-manager/signers/{signer_id}/certificate"
            )))
            .respond_with(ResponseTemplate::new(200).set_body_json(json!({
                "certificatePem": include_str!("../../infisical-api/test-fixtures/end-entity-cert.txt").trim_end(),
                "serialNumber": LEAF_SERIAL,
                "signerName": "release-signer"
            })))
            .expect(2)
            .mount(&server)
            .await;
        Mock::given(method("GET"))
            .and(path(format!(
                "/api/v1/cert-manager/signers/{signer_id}/public-key"
            )))
            .respond_with(ResponseTemplate::new(200).set_body_json(json!({
                "publicKey": RSA_PUBLIC_KEY.trim_end(),
                "algorithm": "RSA_4096"
            })))
            .expect(1)
            .mount(&server)
            .await;
        Mock::given(method("POST"))
            .and(path(format!(
                "/api/v1/cert-manager/signers/{signer_id}/sign"
            )))
            .and(body_json(json!({
                "data": "AQID",
                "signingAlgorithm": "RSASSA_PKCS1_V1_5_SHA_256",
                "isDigest": false,
                "clientMetadata": { "tool": "signtool" }
            })))
            .respond_with(ResponseTemplate::new(200).set_body_json(json!({
                "signature": "BAUG",
                "signingAlgorithm": "RSASSA_PKCS1_V1_5_SHA_256",
                "signerId": signer_id
            })))
            .expect(1)
            .mount(&server)
            .await;

        for (name, arguments) in [
            ("codeSigners.list", json!({ "projectId": project_id })),
            (
                "codeSigners.get",
                json!({ "projectId": project_id, "signerId": signer_id }),
            ),
            (
                "codeSigners.certificate.export",
                json!({ "projectId": project_id, "signerId": signer_id }),
            ),
            (
                "codeSigners.publicKey.get",
                json!({ "projectId": project_id, "signerId": signer_id }),
            ),
        ] {
            let result = dispatch_tool(&client, None, request(name, &arguments))
                .await
                .unwrap();
            assert_eq!(result.is_error, Some(false), "{name}");
            if name == "codeSigners.publicKey.get" {
                assert_eq!(result.structured_content.unwrap()["algorithm"], "RSA_2048");
            }
        }
        let sign_result = dispatch_tool(
            &client,
            None,
            request(
                "codeSigners.sign",
                &json!({
                    "target": { "projectId": project_id, "signerId": signer_id },
                    "data": "AQID",
                    "signingAlgorithm": "RSASSA_PKCS1_V1_5_SHA_256",
                    "clientMetadata": { "tool": "signtool" },
                    "confirm": true
                }),
            ),
        )
        .await
        .unwrap();
        assert_eq!(sign_result.is_error, Some(false));
        assert_eq!(
            sign_result.structured_content.unwrap()["signature"],
            json!("BAUG")
        );
    }

