    #[test]
    fn ssh_tool_family_classifier_is_closed() {
        for name in [
            "sshCertificateAuthorities.list",
            "sshCertificateAuthorities.get",
            "sshCertificateAuthorities.publicKey.get",
            "sshCertificateAuthorities.create",
            "sshCertificateAuthorities.replace",
            "sshCertificateAuthorities.delete",
            "sshCertificateTemplates.list",
            "sshCertificateAuthorities.templates.list",
            "sshCertificateTemplates.get",
            "sshCertificateTemplates.create",
            "sshCertificateTemplates.replace",
            "sshCertificateTemplates.delete",
            "sshCertificates.sign",
            "sshCertificates.issue",
            "sshHosts.list",
            "sshHosts.get",
            "sshHosts.create",
            "sshHosts.replace",
            "sshHosts.delete",
            "sshHosts.userCaPublicKey.get",
            "sshHosts.hostCaPublicKey.get",
            "sshHosts.hostCertificate.issue",
            "sshHostGroups.list",
            "sshHostGroups.get",
            "sshHostGroups.create",
            "sshHostGroups.replace",
            "sshHostGroups.delete",
            "sshHostGroups.hosts.list",
            "sshHostGroups.hosts.add",
            "sshHostGroups.hosts.remove",
        ] {
            assert!(is_ssh_tool(name), "{name}");
        }
        for name in [
            "server.info",
            "certificateAuthorities.list",
            "codeSigners.list",
            "sshCertificateAuthorities.sign",
        ] {
            assert!(!is_ssh_tool(name), "{name}");
        }
    }

    #[test]
    fn ssh_ca_inputs_are_closed_and_consume_imported_private_keys() {
        let project_id = "11111111-1111-4111-8111-111111111111";
        let mut params = request(
            "sshCertificateAuthorities.create",
            &json!({
                "projectId": project_id,
                "friendlyName": "external-ca",
                "keyMaterial": {
                    "keySource": "external",
                    "publicKey": ssh_public_key(),
                    "privateKey": ssh_private_key()
                },
                "confirm": true
            }),
        );
        let input = parse_arguments::<SshCertificateAuthorityCreateInput>(
            &mut params,
            "sshCertificateAuthorities.create arguments do not match the declared schema",
        )
        .unwrap();
        assert!(params.arguments.is_none());
        let debug = format!("{input:?}");
        assert!(debug.contains("[REDACTED]"));
        assert!(!debug.contains(SSH_PRIVATE_KEY_CANARY));

        assert_unknown_field_rejected::<SshCertificateAuthorityCreateInput>(
            "sshCertificateAuthorities.create",
            &json!({
                "projectId": project_id,
                "friendlyName": "external-ca",
                "keyMaterial": {
                    "keySource": "external",
                    "publicKey": ssh_public_key(),
                    "privateKey": ssh_private_key(),
                    "privateKy": "typo"
                },
                "confirm": true
            }),
        );
        assert_unknown_field_rejected::<SshCertificateTemplateCreateInput>(
            "sshCertificateTemplates.create",
            &json!({
                "target": {
                    "projectId": project_id,
                    "sshCaId": "22222222-2222-4222-8222-222222222222"
                },
                "policy": {
                    "name": "deploy",
                    "ttl": "1h",
                    "maxTTL": "24h",
                    "allowedUsers": ["deploy"],
                    "allowedHosts": ["*.example.com"],
                    "allowUserCertificates": true,
                    "allowHostCertificates": true,
                    "allowCustomKeyIds": false,
                    "allowCustomKeyId": true
                },
                "confirm": true
            }),
        );
    }

