    #[test]
    fn maximum_accepted_certificate_issuance_material_fits_the_result_budget() {
        fn pem_shaped_bytes(length: usize) -> String {
            let mut value = String::with_capacity(length);
            while value.len() < length {
                value
                    .push_str("AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\n");
            }
            value.truncate(length);
            value
        }

        let part = MAX_CERTIFICATE_ISSUANCE_MATERIAL_BYTES / 4;
        let output = CertificateIssueOutput {
            outcome: CertificateIssueOutcomeKind::Issued,
            project_id: "11111111-1111-4111-8111-111111111111".to_owned(),
            profile_id: "22222222-2222-4222-8222-222222222222".to_owned(),
            request_id: "33333333-3333-4333-8333-333333333333".to_owned(),
            status: None,
            certificate_id: Some("44444444-4444-4444-8444-444444444444".to_owned()),
            serial_number: Some("A".repeat(128)),
            certificate: Some(pem_shaped_bytes(part)),
            issuing_ca_certificate: Some(pem_shaped_bytes(part)),
            certificate_chain: Some(pem_shaped_bytes(part)),
            private_key: Some(SecretValue::new(pem_shaped_bytes(part))),
            secret_file: None,
        };
        let result = super::structured(output).unwrap();
        let serialized = serde_json::to_string(&result).unwrap();

        assert!(
            serialized.len() <= super::MAX_TOOL_RESULT_BYTES,
            "the API's accepted issued-material aggregate must fit both MCP result encodings"
        );
    }

    #[test]
    fn an_oversized_result_is_refused_rather_than_truncated() {
        let payload = json!({ "records": "x".repeat(super::MAX_TOOL_RESULT_BYTES) });
        let result = super::enforce_result_budget(
            "projects.list",
            None,
            rmcp::model::CallToolResult::structured(payload),
        );

        assert_eq!(result.is_error, Some(true));
        assert!(
            result.structured_content.is_none(),
            "an over-limit result must not deliver a shortened payload that reads as complete"
        );

        let message = result
            .content
            .iter()
            .filter_map(|block| block.as_text().map(|text| text.text.clone()))
            .collect::<String>();
        assert!(message.contains("projects.list"), "{message}");
        assert!(
            message.contains(&super::MAX_TOOL_RESULT_BYTES.to_string()),
            "{message}"
        );
        assert!(
            !message.contains("xxxx"),
            "the refusal must not echo the payload it rejected"
        );
    }

    #[test]
    fn an_oversized_result_still_delivers_its_staged_reference() {
        let payload = json!({
            "publicKey": "x".repeat(super::MAX_TOOL_RESULT_BYTES),
            "secretFile": {
                "uri": "mcp-file://infisical/budget-survivor",
                "name": "kms.keys.privateKeys.bulkReveal.json",
                "mimeType": "application/json"
            }
        });
        let result = super::enforce_result_budget(
            "kms.keys.privateKeys.bulkReveal",
            None,
            rmcp::model::CallToolResult::structured(payload),
        );

        assert_eq!(result.is_error, Some(true));
        let message = result
            .content
            .iter()
            .filter_map(|block| block.as_text().map(|text| text.text.clone()))
            .collect::<String>();
        assert!(
            message.contains("mcp-file://infisical/budget-survivor"),
            "the delivery a non-replayed operation already made must survive the budget: \
             {message}"
        );
    }

    #[tokio::test]
    async fn an_executor_never_echoes_the_secret_it_carried() {
        let server = MockServer::start().await;
        let client = client(&server).await;

        Mock::given(method("POST"))
            .and(path("/api/v4/secrets/STRIPE_API_KEY"))
            .respond_with(ResponseTemplate::new(200).set_body_json(json!({
                "secret": {
                    "id": "secret-1",
                    "_id": "secret-1",
                    "workspace": "project-1",
                    "environment": "prod",
                    "version": 1,
                    "type": "shared",
                    "secretKey": "STRIPE_API_KEY",
                    "secretValue": "executor-envelope-canary",
                    "secretComment": "",
                    "createdAt": "2026-07-19T12:00:00.000Z",
                    "updatedAt": "2026-07-19T12:05:00.000Z",
                    "secretValueHidden": true
                }
            })))
            .mount(&server)
            .await;

        // The envelope adds a deserialization step between the request and the
        // typed input. Moving the arguments rather than copying them is what
        // keeps the value out of an ordinary String, and this is what proves it.
        let result = dispatch(
            &client,
            None,
            request(
                "infisical.write",
                &json!({
                    "operation": "secrets.create",
                    "arguments": {
                        "target": {
                            "projectId": "8f1a0b2c-3d4e-5f60-8a9b-0c1d2e3f4a5b",
                            "environment": "prod",
                            "path": "/payments",
                            "name": "STRIPE_API_KEY"
                        },
                        "secretValue": "executor-envelope-canary"
                    }
                }),
            ),
        )
        .await
        .unwrap();

        let serialized = serde_json::to_string(&result).unwrap();
        assert!(
            !serialized.contains("executor-envelope-canary"),
            "the executor must not return the secret it was given"
        );
        assert_eq!(result.is_error, Some(false), "{serialized}");
    }

    fn test_plane() -> Arc<SecretFilePlane> {
        SecretFilePlane::new(crate::files::FileConfig {
            public_origin: "http://localhost:8000".to_owned(),
            ttl: std::time::Duration::from_mins(1),
            max_staged: 4,
        })
    }

    /// Fetch one staged envelope the way the gateway would: authorize, then download.
    fn download_envelope(plane: &Arc<SecretFilePlane>, uri: &str) -> Value {
        let authorized = plane.authorize_download(uri).expect("authorize download");
        let credential =
            authorized.download.headers[crate::files::TRANSFER_CREDENTIAL_HEADER].clone();
        let download_id = authorized
            .download
            .url
            .rsplit('/')
            .next()
            .expect("download URL ends in an identifier");
        let bytes = plane
            .serve(download_id, &credential)
            .expect("serve download");
        serde_json::from_slice(bytes.as_ref()).expect("envelope is JSON")
    }

    fn reveal_target() -> Value {
        json!({
            "projectId": "8f1a0b2c-3d4e-5f60-8a9b-0c1d2e3f4a5b",
            "environment": "prod",
            "path": "/payments",
            "name": "STRIPE_API_KEY"
        })
    }

    async fn mount_reveal(server: &MockServer, canary: &str) {
        Mock::given(method("GET"))
            .and(path("/api/v4/secrets/STRIPE_API_KEY"))
            .respond_with(ResponseTemplate::new(200).set_body_json(json!({
                "secret": {
                    "id": "secret-1",
                    "environment": "prod",
                    "version": 3,
                    "type": "shared",
                    "secretKey": "STRIPE_API_KEY",
                    "secretValue": canary,
                    "secretPath": "/payments"
                }
            })))
            .expect(1)
            .mount(server)
            .await;
    }

    #[tokio::test]
    async fn reference_delivery_stages_the_value_instead_of_returning_it() {
        let server = MockServer::start().await;
        let client = client(&server).await;
        mount_reveal(&server, "reference-delivery-canary").await;
        let plane = test_plane();

        let result = dispatch(
            &client,
            Some(&plane),
            request(
                "infisical.read",
                &json!({
                    "operation": "secrets.reveal",
                    "arguments": { "target": reveal_target() }
                }),
            ),
        )
        .await
        .unwrap();

        let serialized = serde_json::to_string(&result).unwrap();
        assert!(
            !serialized.contains("reference-delivery-canary"),
            "no part of the result may carry the secret value: {serialized}"
        );
        let structured = result.structured_content.unwrap();
        assert!(
            structured.get("secretValue").is_none(),
            "reference delivery must omit the inline field entirely"
        );
        let uri = structured["secretFile"]["uri"].as_str().unwrap();
        assert!(uri.starts_with(crate::files::STAGED_URI_PREFIX));
        assert_eq!(structured["secretFile"]["mimeType"], "application/json");
        assert_eq!(structured["name"], "STRIPE_API_KEY");

        let envelope = download_envelope(&plane, uri);
        assert_eq!(envelope["operation"], "secrets.reveal");
        assert_eq!(envelope["data"]["secretValue"], "reference-delivery-canary");
    }

