    /// Stage one uploaded value the way the gateway would: authorize, then PUT.
    fn upload_value(plane: &SecretFilePlane, value: &[u8]) -> String {
        let authorized = plane
            .authorize_upload(crate::files::AuthorizeUploadParams::default())
            .expect("authorize upload");
        let upload_id = authorized
            .upload
            .url
            .rsplit('/')
            .next()
            .expect("upload URL ends in an identifier");
        let credential = authorized
            .upload
            .headers
            .get(crate::files::TRANSFER_CREDENTIAL_HEADER)
            .expect("descriptor carries the credential");
        plane
            .claim_upload(upload_id, credential)
            .expect("claim upload")
            .complete(zeroize::Zeroizing::new(value.to_vec()))
            .expect("complete upload");
        authorized.file.uri
    }

    #[test]
    fn the_write_executor_advertises_the_file_input_where_a_gateway_evaluates_it() {
        let catalog = super::catalog();
        let executor = catalog
            .tools
            .iter()
            .find(|tool| tool.name == "infisical.write")
            .expect("the write executor is published");
        let schema = Value::Object((*executor.input_schema).clone());
        for field in [
            "secretValueFile",
            "certificateFile",
            "privateKeyFile",
            "certificateChainFile",
        ] {
            assert_eq!(
                schema.pointer(&format!("/properties/arguments/properties/{field}/$ref")),
                Some(&json!("#/$defs/file")),
                "each named upload field resolves through the executor schema"
            );
        }
        assert_eq!(
            schema.pointer("/$defs/file/x-mcp-file/transferModes/0"),
            Some(&json!("upload")),
            "a file-aware intermediary evaluates referenced annotations in the executor schema"
        );
        for name in [
            "infisical.read",
            "infisical.readAudited",
            "infisical.destroy",
        ] {
            let other = catalog
                .tools
                .iter()
                .find(|tool| tool.name == name)
                .expect("executor is published");
            let schema = Value::Object((*other.input_schema).clone());
            assert_eq!(
                schema.pointer("/properties/arguments/properties"),
                None,
                "{name} carries no file-input annotation"
            );
        }
    }

