    #[test]
    fn file_delivery_wipes_the_inline_text_twin_of_the_staged_payload() {
        let fixture = json!({ "secretValue": "not-a-real-secret-fixture" });
        let mut result = rmcp::model::CallToolResult::structured(fixture.clone());
        let payload = super::take_payload_wiping_text(&mut result).expect("payload extracted");
        assert_eq!(payload, fixture, "staging must receive the full payload");
        let wiped = result.content.iter().any(
            |block| matches!(block, rmcp::model::ContentBlock::Text(text) if text.text.is_empty()),
        );
        assert!(wiped, "the text twin must be wiped, not merely dropped");
        assert!(
            super::take_payload_wiping_text(&mut result).is_none(),
            "an already-consumed result has no payload"
        );
    }

    #[test]
    fn the_budget_error_offers_file_delivery_only_for_repeatable_calls() {
        let plane = test_plane();
        let text_of = |result: rmcp::model::CallToolResult| {
            result
                .content
                .iter()
                .filter_map(|block| block.as_text().map(|text| text.text.clone()))
                .collect::<String>()
        };

        let payload = json!({ "records": "x".repeat(super::MAX_TOOL_RESULT_BYTES) });
        let repeatable = super::enforce_result_budget(
            "projects.list",
            Some(&plane),
            rmcp::model::CallToolResult::structured(payload.clone()),
        );
        assert!(text_of(repeatable).contains("resultDelivery"));

        // A non-replayed effect must never be pointed at a retry path.
        let applied = super::enforce_result_budget(
            "secrets.create",
            Some(&plane),
            rmcp::model::CallToolResult::structured(payload),
        );
        let message = text_of(applied);
        assert!(!message.contains("resultDelivery"), "{message}");
    }

