    #[test]
    fn multi_secret_reveals_stage_one_envelope_for_the_whole_set() {
        let plane = test_plane();
        let disposition = SecretDisposition::Reference(plane.reserve().expect("reserve a slot"));

        let output = SqlGeneratedCredentialsOutput::deliver(
            SqlGeneratedCredentials {
                rotation_id: "rotation-1".into(),
                provider: SqlSecretRotationProvider::Postgres,
                active_index: 0,
                credentials: vec![SqlGeneratedCredential {
                    username: "app_user".into(),
                    password: SecretValue::new("sql-envelope-canary"),
                }],
            },
            disposition,
        )
        .unwrap();

        let serialized = serde_json::to_value(&output).unwrap();
        assert!(
            !serialized.to_string().contains("sql-envelope-canary"),
            "the inline part must be value-free"
        );
        assert!(serialized.get("credentials").is_none());

        let envelope = download_envelope(&plane, serialized["secretFile"]["uri"].as_str().unwrap());
        assert_eq!(
            envelope["operation"],
            "secretRotations.sql.generatedCredentials.get"
        );
        assert_eq!(envelope["data"]["credentials"][0]["username"], "app_user");
        assert_eq!(
            envelope["data"]["credentials"][0]["password"],
            "sql-envelope-canary"
        );
    }

