    /// Extract the JSON object an executor description advertises as an example.
    fn advertised_example(description: &str) -> Option<Value> {
        let start = description.find("Example: ")? + "Example: ".len();
        let body = &description[start..];
        let end = body.rfind("}}")? + 2;
        Some(serde_json::from_str(&body[..end]).expect("an example must be JSON"))
    }

    #[test]
    fn the_destroy_description_names_every_operation_without_a_confirmation() {
        // The destroy executor publishes a safety guarantee. An operation added
        // here without a confirmation field, or one whose field is removed,
        // silently makes that guarantee false for the most dangerous surface,
        // so the exceptions are enumerated rather than described loosely.
        let exempt: std::collections::HashSet<&str> =
            ["dynamicSecretLeases.create"].into_iter().collect();

        let mut without: Vec<String> = super::operations()
            .into_iter()
            .filter(|tiered| tiered.tier == super::ToolTier::Destroy)
            .filter(|tiered| {
                !tiered.tool.input_schema["properties"]
                    .as_object()
                    .is_some_and(|properties| {
                        properties
                            .keys()
                            .any(|field| field.to_lowercase().contains("confirm"))
                    })
            })
            .map(|tiered| tiered.tool.name.to_string())
            .collect();
        without.sort();

        let observed: std::collections::HashSet<&str> =
            without.iter().map(String::as_str).collect();
        assert_eq!(
            observed, exempt,
            "the destroy description enumerates the operations without a confirmation field; \
             this set changed"
        );

        let description = super::catalog()
            .tools
            .into_iter()
            .find(|tool| tool.name == super::INFISICAL_DESTROY_TOOL)
            .and_then(|tool| tool.description.map(|text| text.to_string()))
            .expect("the destroy executor is published");
        // Both surfaces publish this guarantee. Correcting one and leaving the
        // other is how the executor description and the server instructions
        // came to disagree about the same operation.
        for name in &exempt {
            assert!(
                description.contains(name),
                "{name} takes no confirmation and must be named in the destroy description"
            );
            // Naming the operation is not enough: the instructions already
            // mention it among the one-time secret outputs, so a bare
            // containment check holds no matter what the confirmation
            // sentence says. The exemption itself has to be present.
            assert!(
                crate::MCP_INSTRUCTIONS.contains(&format!("except {name}")),
                "the server instructions must state that {name} takes no confirmation"
            );
        }
    }

    #[tokio::test]
    async fn every_executor_advertises_an_example_its_operation_accepts() {
        // Approximating the schema in the test kept leaving gaps: regular
        // expressions, unknown nested fields, and the domain parsers that turn
        // a string into a ProjectId or SecretPath are not expressible that way.
        // Submitting the example through the real dispatch path exercises the
        // deserializer and every validator an actual call would meet, so
        // acceptance is established rather than approximated.
        let server = MockServer::start().await;
        let client = unused_client(&server);

        for tool in super::catalog().tools {
            let description = tool.description.as_deref().unwrap_or_default();
            let Some(example) = advertised_example(description) else {
                assert!(
                    super::executor_tier(tool.name.as_ref()).is_none(),
                    "{} is an executor and must advertise an example call",
                    tool.name
                );
                continue;
            };

            let operation = example["operation"]
                .as_str()
                .expect("an example names an operation");
            assert_eq!(
                super::tool_tier(operation).map(super::ToolTier::executor),
                Some(tool.name.as_ref()),
                "{} advertises {operation}, which it does not serve",
                tool.name
            );

            let outcome = dispatch(
                &client,
                None,
                CallToolRequestParams::new(tool.name.to_string())
                    .with_arguments(example.as_object().expect("object example").clone()),
            )
            .await;

            // Reaching upstream is success here: the request got past every
            // validator and failed only because no route is mounted. A
            // rejection before that point means the example is not callable.
            if let Err(error) = outcome {
                assert_ne!(
                    error.code,
                    rmcp::model::ErrorCode::INVALID_PARAMS,
                    "{}: the advertised example is rejected as invalid: {}",
                    tool.name,
                    error.message
                );
            }
        }
    }

    #[tokio::test]
    async fn a_rejected_call_shows_the_corrected_form() {
        let server = MockServer::start().await;
        let client = unused_client(&server);

        let wrong_tier = dispatch(
            &client,
            None,
            request(
                "infisical.read",
                &json!({ "operation": "secrets.delete", "arguments": {} }),
            ),
        )
        .await
        .unwrap_err();
        assert!(
            wrong_tier.message.contains("infisical.destroy"),
            "a tier mismatch must name the executor that serves it: {}",
            wrong_tier.message
        );
        // Naming the executor is not enough: the caller has to be told what to
        // do with it, and why the arguments are absent rather than forgotten.
        assert!(
            wrong_tier
                .message
                .contains("Resend this request to infisical.destroy"),
            "a tier mismatch must say to resend the request there: {}",
            wrong_tier.message
        );
        assert!(
            wrong_tier.message.contains("may carry a secret"),
            "a tier mismatch must say why the arguments are not repeated: {}",
            wrong_tier.message
        );
        assert!(
            !wrong_tier.message.contains("{...}") && !wrong_tier.message.contains("..."),
            "a refusal must not present a form that cannot be submitted: {}",
            wrong_tier.message
        );

        let with_secret = dispatch(
            &client,
            None,
            request(
                "infisical.read",
                &json!({
                    "operation": "secrets.delete",
                    "arguments": { "secretValue": "refusal-echo-canary" }
                }),
            ),
        )
        .await
        .unwrap_err();
        assert!(
            !with_secret.message.contains("refusal-echo-canary"),
            "a refusal must not repeat arguments that may carry a secret: {}",
            with_secret.message
        );

        // A name is caller-controlled and can hold a misplaced credential, so no
        // part of it may come back. Asserting the refusal is byte-identical for
        // every input is stronger than searching it for fragments: a constant
        // message cannot carry anything, whatever the input contained.
        let mut refusals = Vec::new();
        for operation in [
            "secrets.notReal",
            "projectsList",
            "bad\"quote.get",
            "back\\slash.get",
            ".get",
            "sk1234liveTokenLookalike.get",
            "\u{1f600}.get",
        ] {
            let error = dispatch(
                &client,
                None,
                request(
                    "infisical.read",
                    &json!({ "operation": operation, "arguments": {} }),
                ),
            )
            .await
            .unwrap_err();
            refusals.push(error.message.to_string());
        }

        let first = &refusals[0];
        assert!(
            first.contains("operations.list"),
            "a refusal must say how to find a real name: {first}"
        );
        for refusal in &refusals {
            assert_eq!(
                refusal, first,
                "the refusal must not vary with the name it was given"
            );
        }
        assert!(server.received_requests().await.unwrap().is_empty());
    }

