    #[test]
    fn every_operation_declares_a_tier_matching_its_annotations() {
        for tool in super::operations().into_iter().map(|tiered| tiered.tool) {
            let annotations = tool.annotations.as_ref().expect("annotations required");
            let tier = super::tool_tier(tool.name.as_ref())
                .unwrap_or_else(|| panic!("{} must declare a tier", tool.name));

            let expected = match tier {
                super::ToolTier::Read => (true, false, true),
                super::ToolTier::ReadAudited | super::ToolTier::Write => (false, false, false),
                super::ToolTier::Destroy => (false, true, false),
            };
            let observed = (
                annotations.read_only_hint.expect("read-only required"),
                annotations.destructive_hint.expect("destructive required"),
                annotations.idempotent_hint.expect("idempotent required"),
            );

            assert_eq!(
                observed, expected,
                "{} publishes annotations its declared tier does not produce",
                tool.name
            );
        }
    }

